INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('AAPL', 'published', '{"ticker":"AAPL","description":"Integrated consumer devices, operating systems, software, and services.","lede":"Apple monetizes a tightly integrated installed base through premium devices and a growing portfolio of services.","sells":"iPhone, Mac, iPad, wearables, accessories, software, payments, cloud, media, and warranty services.","revenueModel":"Device sales plus recurring and transaction-based services distributed across Apple’s installed base.","opportunity":"Brand, custom silicon, software integration, distribution, and ecosystem loyalty support premium economics.","mustGoRight":"Apple must keep its devices differentiated, expand services responsibly, and create compelling new reasons to upgrade.","editorNote":"The central question is whether ecosystem strength can offset mature smartphone markets and preserve growth without overreliance on price and buybacks.","bullTitle":"An exceptional installed-base business","bull":["Deep hardware-software integration supports loyalty and premium pricing.","Services can deepen engagement and recurring revenue.","Custom silicon improves product performance and strategic control."],"bearTitle":"A premium franchise facing mature categories","bear":["iPhone remains the economic center of the company.","App distribution and default arrangements face regulatory pressure.","China exposure creates demand, supply-chain, and geopolitical risk."],"thesisBreaker":"A durable decline in ecosystem loyalty or loss of control over critical distribution economics would weaken Apple’s premium-return model.","financialDrivers":[{"label":"Q2 FY26 REVENUE","value":"$111.2B · +17%","detail":"March-quarter revenue from products and services; verify category and geography in the linked statements"},{"label":"SERVICES","value":"$31.0B","detail":"Recurring and transaction revenue with materially different regulation and margin exposure than hardware"},{"label":"OPERATING CASH FLOW","value":">$28B","detail":"Funds product investment, supply commitments, dividends, and repurchases"},{"label":"CAPITAL RETURNS","value":"$100B authorization","detail":"Additional repurchase authorization announced with the April 2026 results; per-share benefit depends on valuation"},{"label":"INSTALLED BASE","value":"Retention and upgrades","detail":"Active devices, replacement cycles, regional mix, and the attach of paid services"},{"label":"SUPPLY & INVENTORY","value":"Execution","detail":"Component availability, manufacturing concentration, channel inventory, freight, tariffs, and product transitions"}],"risks":[{"title":"Product concentration","level":"High","text":"The iPhone anchors device revenue and ecosystem activity.","signal":"Installed-base and upgrade trends"},{"title":"Platform regulation","level":"High","text":"Rules affecting app distribution, payments, and default services could alter economics.","signal":"Remedies affecting commissions or defaults"},{"title":"China exposure","level":"High","text":"Apple depends on China for important demand and manufacturing capacity.","signal":"Regional sales and supply diversification"},{"title":"Distribution and default economics","level":"High","text":"App-store rules, payments, browser defaults, and search arrangements face regulatory remedies and partner renegotiation.","signal":"Services gross margin, commission changes, default contracts, fines, and mandated product changes"},{"title":"Manufacturing and supplier concentration","level":"High","text":"Critical components and assembly remain concentrated among a limited number of suppliers and geographies.","signal":"Supplier diversification, inventory, lead times, tariffs, product availability, and warranty costs"}],"monitor":[{"title":"Installed-base monetization","text":"Track active devices, paid accounts, services mix, churn, and regulatory changes—not services revenue in isolation.","impact":"BULL CASE"},{"title":"Leadership and product cadence","text":"Evaluate execution through leadership transitions, device differentiation, silicon roadmaps, AI features, and upgrade behavior.","impact":"NEUTRAL"},{"title":"China demand and supply concentration","text":"Separate regional consumer demand from manufacturing, supplier, trade, and geopolitical dependencies.","impact":"BEAR CASE"},{"title":"Capital returns versus innovation","text":"Compare repurchases and dividends with R&D, acquisitions, manufacturing commitments, and fully diluted share reduction.","impact":"NEUTRAL"}],"questions":["Which products can become economically material beyond iPhone?","How much services profit depends on distribution terms regulators may change?","Will on-device AI create a measurable replacement cycle or mainly defend retention?","Do repurchases create value at the market price after funding core innovation?","What portion of services profit depends on distribution arrangements vulnerable to remedies?","Which manufacturing dependencies remain hardest to diversify without sacrificing cost or product cadence?"],"competitors":"Samsung, Google, Microsoft, Huawei, Xiaomi, and competing payments and media ecosystems.","sources":[{"title":"Apple SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=320193&owner=exclude","excerpt":"Apple filings describe products, services, geographic and channel exposure, supply-chain commitments, platform regulation, cash, debt, repurchases, and risk factors."},{"title":"Apple Fiscal Q2 2026 Results","meta":"Company press release · April 30, 2026","href":"https://www.apple.com/newsroom/2026/04/apple-reports-second-quarter-results/","excerpt":"The official release reports March-quarter revenue, earnings per share, cash flow, dividend, and additional repurchase authorization."},{"title":"Apple Q2 FY2026 Financial Statements","meta":"Company financial statements","href":"https://www.apple.com/newsroom/pdfs/fy2026q2/FY26_Q2_Consolidated_Financial_Statements.pdf","excerpt":"The statements provide product, services, and geographic sales plus income, balance-sheet, and cash-flow detail."},{"title":"Apple Investor Relations","meta":"Company primary materials","href":"https://investor.apple.com/","excerpt":"Official earnings materials, SEC filings, governance documents, shareholder information, and events."},{"title":"Apple Annual Reports","meta":"Company annual filing archive","href":"https://investor.apple.com/sec-filings/default.aspx","excerpt":"Apple''s annual, quarterly, current, proxy, and ownership filings provide product, geography, supply, cash-flow, share-count, governance, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.apple.com/newsroom/topics/company-news/","comparables":[{"name":"Samsung Electronics","ticker":"005930.KS","ownership":"Public","relationship":"Premium device, component, and ecosystem competitor","valuation":"Compare device mix and semiconductor exposure separately","financialStatus":"Diversified electronics and semiconductor group; not a clean consolidated multiple peer.","sourceUrl":"https://www.samsung.com/global/ir/"},{"name":"Alphabet","ticker":"GOOGL","ownership":"Public","relationship":"Mobile platform, services, AI, and distribution competitor","valuation":"Compare services economics and platform risk, not hardware revenue","financialStatus":"Highly profitable advertising and cloud platform with Android distribution leverage.","sourceUrl":"https://abc.xyz/investor/"},{"name":"Microsoft","ticker":"MSFT","ownership":"Public","relationship":"Operating-system, device, cloud, productivity, and AI competitor","valuation":"Compare recurring revenue, margins, and free-cash-flow durability","financialStatus":"Diversified, highly profitable enterprise and consumer software platform.","sourceUrl":"https://www.microsoft.com/en-us/Investor"},{"name":"Huawei","ticker":"—","ownership":"Private","relationship":"Device, ecosystem, and infrastructure competitor, especially in China","valuation":"No public equity valuation","financialStatus":"Private employee-owned operating company with public annual reports but no traded equity.","sourceUrl":"https://www.huawei.com/en/annual-report"},{"name":"Sony Group","ticker":"SONY","ownership":"Public","relationship":"Consumer hardware, media, gaming, sensors, and ecosystem comparable","valuation":"Separate entertainment, imaging, finance, and hardware segments","financialStatus":"Profitable diversified electronics and entertainment group with different recurring economics.","sourceUrl":"https://www.sony.com/en/SonyInfo/IR/"},{"name":"Xiaomi","ticker":"1810.HK","ownership":"Public","relationship":"Smartphone, device, services, and connected-home competitor","valuation":"Normalize geography, hardware margin, and internet-services mix","financialStatus":"Profitable device ecosystem with lower price points and different regional exposure.","sourceUrl":"https://ir.mi.com/"}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
  status = 'published',
  content_json = excluded.content_json,
  verified_by = excluded.verified_by,
  verified_at = CURRENT_TIMESTAMP,
  published_at = COALESCE(company_dossiers.published_at, CURRENT_TIMESTAMP),
  updated_at = CURRENT_TIMESTAMP;

