INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('NVDA', 'published', '{"ticker":"NVDA","description":"Accelerated computing platforms spanning chips, systems, networking, and software.","lede":"NVIDIA has evolved from a graphics-chip company into a full-stack accelerated-computing platform central to modern AI infrastructure.","sells":"GPUs, networking, systems, software, and platform services for data center, gaming, visualization, automotive, and edge markets.","revenueModel":"Semiconductor and system sales, networking, software licensing, support, and cloud-access services.","opportunity":"AI training and inference are increasing demand for accelerated computing, while CUDA and system-level integration strengthen adoption.","mustGoRight":"Customers must continue earning value from AI infrastructure and NVIDIA must maintain performance, supply, and ecosystem leadership.","editorNote":"The debate is no longer whether AI compute demand exists; it is how durable NVIDIA’s share and returns remain as customers, competitors, and custom silicon mature.","bullTitle":"The full-stack standard for accelerated computing","bull":["CUDA and developer adoption create a powerful software ecosystem.","Chips, networking, systems, and software are co-designed.","Rapid product cadence expands performance and total platform value."],"bearTitle":"Extraordinary demand invites extraordinary competition","bear":["Large customers are developing custom accelerators.","Demand is concentrated among a limited number of major buyers.","Export restrictions and supply dependencies can constrain reachable markets."],"thesisBreaker":"If workload economics shift decisively toward alternative accelerators while NVIDIA’s software advantage erodes, current platform expectations would require reassessment.","financialDrivers":[{"label":"Q1 FY27 REVENUE","value":"$81.6B · +85%","detail":"Official May 2026 results; judge growth against customer concentration, supply, and the durability of AI infrastructure spending"},{"label":"DATA CENTER","value":"$75.2B · +92%","detail":"Compute, networking, systems, and software adoption remain the dominant value driver"},{"label":"GROSS MARGIN","value":"75.0% non-GAAP","detail":"Track mix, product transitions, export controls, supply costs, and competitive pricing"},{"label":"Q2 FY27 OUTLOOK","value":"$91B ±2%","detail":"Company guidance assumed no Data Center compute revenue from China"},{"label":"OPERATING CASH FLOW","value":"Cash conversion","detail":"Compare customer collections, inventory, supplier prepayments, taxes, and capital expenditures with reported earnings"},{"label":"DILUTED SHARE COUNT","value":"Per-share test","detail":"Measure repurchases against stock compensation, employee issuance, and acquisition consideration"}],"risks":[{"title":"Customer concentration","level":"High","text":"A small group of cloud and technology companies drives substantial infrastructure spending.","signal":"Customer capex and order concentration"},{"title":"Custom silicon","level":"High","text":"Hyperscalers and competitors are investing in alternative accelerators.","signal":"Workload share and relative performance"},{"title":"Export controls","level":"High","text":"Restrictions can limit product configurations and addressable markets.","signal":"New rules and license requirements"},{"title":"Product-transition execution","level":"High","text":"Rapid architecture changes can create qualification delays, inventory exposure, supply imbalance, and customer pauses.","signal":"Launch timing, inventory, purchase commitments, transition costs, and customer deployment schedules"},{"title":"Platform concentration and regulation","level":"Medium","text":"CUDA, networking, acquisitions, and market leadership attract competition and regulatory scrutiny across jurisdictions.","signal":"Competition investigations, licensing remedies, developer adoption, and software attach"}],"monitor":[{"title":"Rubin transition and inference economics","text":"Measure time-to-volume, performance per dollar, networking attach, and software monetization rather than relying on benchmark leadership alone.","impact":"BULL CASE"},{"title":"Hyperscaler spending and custom silicon","text":"Separate additive accelerator programs from workloads that permanently move away from NVIDIA''s platform.","impact":"BEAR CASE"},{"title":"Supply and export controls","text":"Track foundry, advanced packaging, memory, optics, system availability, and the revenue pool made inaccessible by regulation.","impact":"NEUTRAL"},{"title":"Per-share cash conversion","text":"Reconcile GAAP earnings, stock compensation, operating cash flow, capex, repurchases, and fully diluted shares.","impact":"NEUTRAL"}],"questions":["What portion of current demand represents recurring production inference rather than one-time capacity buildout?","How much of the platform''s economics comes from networking and software versus accelerators?","Where does custom silicon become a substitute rather than a complement?","Can NVIDIA preserve full-stack returns as customers gain purchasing scale?","What working-capital and supply commitments are required for each architecture transition?","Can software and services become material recurring revenue independent of accelerator cycles?"],"competitors":"AMD, Intel, hyperscaler custom silicon, Broadcom-enabled ASICs, and specialized AI accelerator companies.","sources":[{"title":"NVIDIA SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1045810&owner=exclude","excerpt":"NVIDIA filings describe its platform markets, customer concentration, manufacturing and supply dependencies, export controls, competition, cash generation, and capital returns."},{"title":"NVIDIA Q1 Fiscal 2027 Results","meta":"Company earnings release · May 20, 2026","href":"https://investor.nvidia.com/news/press-release-details/2026/NVIDIA-Announces-Financial-Results-for-First-Quarter-Fiscal-2027/default.aspx","excerpt":"The official release reports revenue, Data Center results, margins, outlook, platform announcements, and the company''s treatment of stock-based compensation in non-GAAP measures."},{"title":"NVIDIA Investor Relations","meta":"Company primary materials","href":"https://investor.nvidia.com/","excerpt":"Official results, CFO commentary, presentations, SEC filings, events, and governance information."},{"title":"NVIDIA SEC filing detail","meta":"Company-hosted filing index · Q1 FY2027 Form 10-Q","href":"https://investor.nvidia.com/financial-info/sec-filings/sec-filings-details/default.aspx?FilingId=19467022","excerpt":"The quarterly filing provides the accounting, concentration, liquidity, risk, and segment evidence behind the earnings release."},{"title":"NVIDIA Annual Reports and Proxies","meta":"Company governance and annual filing archive","href":"https://investor.nvidia.com/financial-info/annual-reports-and-proxies/default.aspx","excerpt":"Annual reports and proxy materials provide business, governance, executive compensation, share-count, capital-allocation, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://nvidianews.nvidia.com/news/latest","comparables":[{"name":"Advanced Micro Devices","ticker":"AMD","ownership":"Public","relationship":"Direct accelerator and CPU competitor","valuation":"Use live market value and EV/revenue above","financialStatus":"Profitable semiconductor platform investing to expand accelerator software and systems share.","sourceUrl":"https://ir.amd.com/"},{"name":"Broadcom","ticker":"AVGO","ownership":"Public","relationship":"Networking and custom-accelerator enabler","valuation":"Compare semiconductor growth, margins, and free-cash-flow yield","financialStatus":"Diversified semiconductor and infrastructure-software company with material custom-silicon exposure.","sourceUrl":"https://investors.broadcom.com/"},{"name":"Intel","ticker":"INTC","ownership":"Public","relationship":"CPU, accelerator, foundry, and platform competitor","valuation":"Asset-heavy turnaround; earnings multiples need normalization","financialStatus":"Large revenue base with substantial manufacturing investment and restructuring risk.","sourceUrl":"https://www.intc.com/"},{"name":"Hyperscaler custom silicon","ticker":"—","ownership":"Private","relationship":"Customer-designed substitutes including internal AI accelerators","valuation":"No standalone valuation","financialStatus":"Economics sit inside large cloud platforms; adoption must be measured by workload share, not chip announcements.","sourceUrl":"https://www.sec.gov/edgar/search/"},{"name":"Marvell Technology","ticker":"MRVL","ownership":"Public","relationship":"Networking and custom-compute comparable","valuation":"Compare data-center growth, margin, and customer concentration","financialStatus":"Smaller semiconductor supplier with meaningful cloud infrastructure exposure.","sourceUrl":"https://investor.marvell.com/"},{"name":"Cerebras Systems","ticker":"PRIVATE","ownership":"Private","relationship":"Specialized AI systems and accelerator competitor","valuation":"No continuously observable public valuation","financialStatus":"Private disclosures provide less complete financial and customer-concentration evidence.","sourceUrl":"https://www.cerebras.ai/"}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
  status = 'published',
  content_json = excluded.content_json,
  verified_by = excluded.verified_by,
