INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('CAT', 'published', '{"ticker":"CAT","description":"Heavy machinery, engines, energy systems, services, and equipment finance.","lede":"Caterpillar pairs a global installed base of mission-critical equipment with dealers, parts, services, technology, and financing.","sells":"Construction and mining equipment, diesel and natural-gas engines, industrial turbines, locomotives, parts, services, and financing.","revenueModel":"Equipment and engine sales plus aftermarket parts, services, rentals, digital offerings, and finance income.","opportunity":"Infrastructure, mining, energy, and replacement demand support equipment sales while the installed base drives recurring aftermarket activity.","mustGoRight":"Caterpillar must manage the cycle, preserve price discipline, support dealers, and grow services without sacrificing customer economics.","editorNote":"Caterpillar should be analyzed as both a cyclical manufacturer and an installed-base services franchise; the balance between those identities drives through-cycle quality.","bullTitle":"A global installed base with dealer reach","bull":["A large field population creates recurring parts and service demand.","Independent dealers provide local relationships and service capacity.","Energy and mining exposure can diversify construction cycles."],"bearTitle":"High-quality execution cannot remove cyclicality","bear":["Construction and resource spending can decline sharply.","Dealer inventory movements can amplify demand changes.","Input costs, currency, and financing conditions affect customers and margins."],"thesisBreaker":"Sustained erosion in dealer strength, installed-base economics, or aftermarket share would weaken Caterpillar’s principal advantages beyond an ordinary cycle.","financialDrivers":[{"label":"Q1 SALES & REVENUE","value":"$17.4B · +22%","detail":"Volume and price realization drove growth; segment and end-market mix determine profit quality"},{"label":"OPERATING MARGIN","value":"17.7% GAAP","detail":"Price, volume, manufacturing cost, currency, mix, and restructuring"},{"label":"ENTERPRISE CASH FLOW","value":"$1.9B","detail":"First-quarter operating cash flow before the timing of working capital and capital allocation"},{"label":"CAPITAL RETURNS","value":"$5.7B in Q1","detail":"$5.0B of repurchases and $0.7B of dividends; judge repurchases against cycle and valuation"},{"label":"SERVICES REVENUE","value":"Installed-base value","detail":"Parts, maintenance, digital, remanufacturing, dealer capability, and fleet utilization"},{"label":"DEALER INVENTORY","value":"Demand quality","detail":"End-user sales versus dealer stocking, order backlog, cancellations, and production scheduling"}],"risks":[{"title":"End-market cycle","level":"High","text":"Construction, mining, and energy capital spending can contract.","signal":"Retail sales and dealer inventory"},{"title":"Dealer health","level":"Medium","text":"Distribution quality depends on financially capable independent dealers.","signal":"Dealer liquidity and inventory aging"},{"title":"Global trade exposure","level":"Medium","text":"Tariffs, currency, supply chains, and local competition affect results.","signal":"Trade restrictions and regional price pressure"},{"title":"Cycle and commodity exposure","level":"High","text":"Construction, mining, energy, transportation, and customer financing respond to rates, commodity prices, and investment cycles.","signal":"Retail sales, backlog, dealer inventory, commodity prices, utilization, and credit losses"},{"title":"Financial Products and credit","level":"Medium","text":"Dealer and customer financing supports sales but adds funding, residual-value, delinquency, and concentration risk.","signal":"Past dues, credit losses, financing receivables, funding cost, and used-equipment values"}],"monitor":[{"title":"Dealer inventory and end-user demand","text":"Compare reported sales with retail statistics, dealer inventories, order rates, backlog, utilization, and rental fleets.","impact":"NEUTRAL"},{"title":"Power & Energy mix","text":"Track data-center, oil-and-gas, turbine, engine, aftermarket, and distributed-power growth and margins.","impact":"BULL CASE"},{"title":"Price-cost and capital returns","text":"Measure price realization against labor, freight, components, tariffs, currency, and the value created by repurchases.","impact":"BEAR CASE"},{"title":"Orders versus dealer inventory","text":"Separate end-user demand and services activity from dealer stocking or destocking across regions and industries.","impact":"NEUTRAL"}],"questions":["How much current growth is end demand versus dealer restocking?","Can Power & Energy structurally raise Caterpillar''s through-cycle earnings quality?","What margin is sustainable when price-cost tailwinds normalize?","Do repurchases create per-share value near peak-cycle earnings?","How much through-cycle value comes from services versus original equipment?","What financing and residual-value losses are implied by a severe mining or construction downturn?"],"competitors":"Komatsu, Deere, Volvo Construction Equipment, Hitachi Construction Machinery, Cummins, and regional manufacturers.","sources":[{"title":"Caterpillar SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=18230&owner=exclude","excerpt":"Caterpillar filings report Construction Industries, Resource Industries, Power & Energy, Financial Products, dealer inventory, cash, financing, competition, and risk."},{"title":"Caterpillar Q1 2026 Results","meta":"Company earnings release · April 30, 2026","href":"https://investors.caterpillar.com/financials/quarterly-results/default.aspx","excerpt":"The official results page reports sales, operating margin, earnings per share, cash flow, capital returns, segment results, retail statistics, and links to the Form 10-Q."},{"title":"Caterpillar Events and Presentations","meta":"Company primary materials","href":"https://investors.caterpillar.com/events-presentations/default.aspx","excerpt":"Official earnings slides, webcasts, transcripts, investor presentations, and event materials."},{"title":"Caterpillar Investor Relations","meta":"Company primary materials","href":"https://investors.caterpillar.com/","excerpt":"Quarterly results, SEC filings, governance, financial history, retail statistics, and shareholder information."},{"title":"Caterpillar Annual Reports","meta":"Company annual filing archive","href":"https://investors.caterpillar.com/financials/annual-reports/default.aspx","excerpt":"Annual reports describe segments, dealers, services, backlog, inventory, Financial Products, cash flow, capital returns, and risk."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investors.caterpillar.com/news/default.aspx","comparables":[{"name":"Komatsu","ticker":"6301.T","ownership":"Public","relationship":"Global construction and mining equipment competitor","valuation":"Compare geography, mining mix, aftermarket, and currency","financialStatus":"Profitable Japanese equipment manufacturer with broad mining and construction exposure.","sourceUrl":"https://www.komatsu.jp/en/ir/"},{"name":"Deere & Company","ticker":"DE","ownership":"Public","relationship":"Heavy equipment, precision technology, and finance comparable","valuation":"Agriculture-cycle exposure differs from Caterpillar","financialStatus":"Profitable equipment manufacturer with a large captive-finance operation.","sourceUrl":"https://investor.deere.com/"},{"name":"Cummins","ticker":"CMI","ownership":"Public","relationship":"Engine, power-generation, components, and distribution competitor","valuation":"Compare power exposure, margins, and cash conversion","financialStatus":"Profitable diversified power supplier investing across traditional and lower-carbon technologies.","sourceUrl":"https://investor.cummins.com/"},{"name":"Hitachi Construction Machinery","ticker":"6305.T","ownership":"Public","relationship":"Construction and mining equipment competitor","valuation":"Compare dealer, rental, mining, and regional mix","financialStatus":"Public Japanese machinery company with global mining and construction exposure.","sourceUrl":"https://www.hitachicm.com/global/en/ir/"},{"name":"Volvo Group","ticker":"VOLV-B.ST","ownership":"Public","relationship":"Heavy equipment, engines, trucks, services, and finance competitor","valuation":"Normalize currency, truck cycle, and finance operations","financialStatus":"Profitable global industrial platform with meaningful commercial-vehicle exposure.","sourceUrl":"https://www.volvogroup.com/en/investors.html"},{"name":"CNH Industrial","ticker":"CNH","ownership":"Public","relationship":"Construction and agricultural equipment comparable","valuation":"Agriculture mix and finance operations require separation","financialStatus":"Cyclical equipment manufacturer with a different end-market mix and scale.","sourceUrl":"https://www.cnh.com/investors"}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
