INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('BB', 'published', '{"ticker":"BB","description":"Safety-certified embedded software, secure communications, cryptography, and connected-asset technology.","lede":"BlackBerry is now an infrastructure-software company centered on QNX embedded systems and Secure Communications rather than the handset business that made its name.","sells":"QNX operating systems, hypervisors, development tools, automotive middleware, secure communications, endpoint management, cryptography, and connected-asset services.","revenueModel":"Software licenses, support and maintenance, professional services, recurring subscriptions, volume-based QNX royalties, and intellectual-property licensing.","opportunity":"More software inside safety-critical vehicles and industrial systems can expand QNX design wins, royalty backlog, developer adoption, and lifecycle revenue.","mustGoRight":"QNX design wins must convert into production royalties, platform investment must keep pace with automotive architectures, and Secure Communications must remain relevant and cash generative.","editorNote":"The owner’s work is to separate design-win announcements and estimated royalty backlog from recognized revenue, production volumes, renewal economics, and cash conversion.","bullTitle":"A trusted operating layer for safety-critical systems","bull":["QNX has a long operating history in embedded and safety-certified environments.","Automotive software complexity can increase the value of operating systems, hypervisors, middleware, and development tools.","Royalty-bearing designs can monetize over long vehicle production lives after development investment is incurred."],"bearTitle":"Design wins are not the same as near-term revenue","bear":["Automotive programs have long development cycles and production volumes can differ from customer forecasts.","Open-source and large technology platforms compete for the embedded software layer.","Secure Communications operates in mature, competitive markets and must fund continued product investment."],"thesisBreaker":"A sustained failure of QNX design wins and royalty backlog to convert into growing, durable software revenue would break the embedded-platform thesis.","financialDrivers":[{"label":"QNX ROYALTIES","value":"Vehicle programs","detail":"Design wins, production volumes, royalty timing, pricing, and the conversion of backlog into revenue"},{"label":"DEVELOPMENT SEATS","value":"Developer adoption","detail":"Seat growth can lead production royalties but does not guarantee timing or vehicle volume"},{"label":"SECURE COMMUNICATIONS","value":"Recurring resilience","detail":"Government and enterprise renewals, critical-event demand, churn, and operating margin"},{"label":"CAPITAL ALLOCATION","value":"Cash versus growth","detail":"R&D, partnerships, acquisitions, buybacks, and the cash cost of restructuring or separation"},{"label":"ANNUAL RECURRING REVENUE","value":"Retention quality","detail":"QNX development, secure communications, renewals, dollar retention, and contract duration"},{"label":"FREE CASH FLOW","value":"Self-funding test","detail":"Collections, restructuring, working capital, R&D, investment income, and capital returns"}],"risks":[{"title":"Automotive program timing","level":"High","text":"QNX royalty revenue depends on customer launches, unit production, and platform life cycles that BlackBerry does not control.","signal":"Royalty backlog conversion versus new design wins"},{"title":"Platform competition","level":"High","text":"Linux, Android-based systems, proprietary platforms, and competing embedded vendors can pressure adoption and pricing.","signal":"Design-win quality and software content per vehicle"},{"title":"Execution across two businesses","level":"Medium","text":"QNX and Secure Communications have different customers, economics, and investment needs.","signal":"Segment growth, margins, and operating expense discipline"},{"title":"Backlog timing and non-binding assumptions","level":"High","text":"Automotive design wins and royalty backlog depend on vehicle launches, production volumes, program duration, pricing, and customer decisions.","signal":"Vehicle starts, production units, backlog revisions, average royalty, and recognized QNX revenue"},{"title":"Customer concentration and platform substitution","level":"High","text":"OEM consolidation, insourcing, Android, AUTOSAR, open source, and competing embedded platforms can limit content per vehicle.","signal":"Named wins, customer mix, displaced programs, software layers, and pricing"}],"monitor":[{"title":"QNX backlog conversion","text":"Reconcile announced design wins and royalty backlog with vehicle launches, units produced, average royalty, and recognized revenue.","impact":"BULL CASE"},{"title":"Secure Communications retention","text":"Track annual recurring revenue, dollar retention, government wins, churn, and segment operating cash generation.","impact":"NEUTRAL"},{"title":"Automotive architecture competition","text":"Follow OEM insourcing, open-source alternatives, Android Automotive, AUTOSAR, safety certification, and developer adoption.","impact":"BEAR CASE"},{"title":"Cash-backed capital allocation","text":"Compare recurring revenue and operating cash flow with R&D, restructuring, buybacks, acquisitions, and investment balances.","impact":"NEUTRAL"}],"questions":["When and at what economics will the QNX royalty backlog convert?","Which automotive layers can QNX monetize beyond the real-time operating system?","Can Secure Communications grow while preserving certification-led differentiation?","What capital-allocation policy best serves owners now that the portfolio is more focused?","How much disclosed QNX backlog is subject to production-volume assumptions or cancellation?","Which recurring-revenue and cash metrics should replace legacy consolidated measures for owner accountability?"],"competitors":"Wind River, Green Hills Software, Linux and Android ecosystems, Elektrobit, automotive OEM software stacks, Microsoft, and security-platform vendors.","sources":[{"title":"BlackBerry SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1070235&owner=exclude","excerpt":"BlackBerry filings disclose QNX and Secure Communications economics, contracts, backlog measures, cash, investments, restructuring, competition, and risk."},{"title":"BlackBerry Fiscal Q1 2027 Results","meta":"Company results hub · June 25, 2026","href":"https://investors.blackberry.com/","excerpt":"The investor-relations home page links the latest earnings presentation, quarterly report, press release, supplemental information, and replay."},{"title":"BlackBerry Quarterly Results","meta":"Company financial archive","href":"https://investors.blackberry.com/quarterly-results","excerpt":"Official financial information, supplemental data, earnings releases, annual reports, and transcripts by fiscal period."},{"title":"BlackBerry Press Releases","meta":"Company primary materials","href":"https://investors.blackberry.com/press-releases","excerpt":"Official product, customer, partnership, financial, and corporate announcements."},{"title":"BlackBerry Annual Reports","meta":"Company annual filing archive","href":"https://investors.blackberry.com/financial-information/annual-reports","excerpt":"Annual reports provide segment, backlog, revenue-recognition, customer, cash-flow, governance, capital-allocation, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investors.blackberry.com/press-releases","comparables":[{"name":"Aptiv","ticker":"APTV","ownership":"Public","relationship":"Software-defined vehicle architecture and automotive systems comparable","valuation":"Separate software, signal-and-power, and cyclical auto exposure","financialStatus":"Profitable global automotive technology supplier with substantial OEM concentration.","sourceUrl":"https://ir.aptiv.com/"},{"name":"Continental","ticker":"CON.DE","ownership":"Public","relationship":"Parent of Elektrobit and automotive software competitor","valuation":"Conglomerate and restructuring context limits direct comparison","financialStatus":"Large public automotive supplier with software, electronics, and tire operations.","sourceUrl":"https://www.continental.com/en/investors/"},{"name":"Motorola Solutions","ticker":"MSI","ownership":"Public","relationship":"Mission-critical communications and public-safety software comparable","valuation":"Compare recurring software and services growth plus cash conversion","financialStatus":"Profitable communications and command-center platform with strong public-safety exposure.","sourceUrl":"https://www.motorolasolutions.com/en_us/about/investors.html"},{"name":"Wind River","ticker":"—","ownership":"Private","relationship":"Embedded and automotive operating-software competitor","valuation":"No standalone public valuation","financialStatus":"Privately held software platform; customer and segment economics are less transparent than public filings.","sourceUrl":"https://www.windriver.com/"},{"name":"Cerence","ticker":"CRNC","ownership":"Public","relationship":"Automotive software and embedded voice comparable","valuation":"Adjust for leverage, customer concentration, and turnaround risk","financialStatus":"Smaller automotive software vendor with different product and balance-sheet exposure.","sourceUrl":"https://investors.cerence.com/"},{"name":"CrowdStrike","ticker":"CRWD","ownership":"Public","relationship":"Endpoint and enterprise-security comparable","valuation":"Cloud security growth multiples are not directly applicable to Secure Communications","financialStatus":"High-growth cloud security platform with a different customer and delivery model.","sourceUrl":"https://ir.crowdstrike.com/"}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
