INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('BE', 'published', '{"ticker":"BE","description":"Onsite solid-oxide power generation and electrolysis systems for resilient distributed energy.","lede":"Bloom Energy builds modular solid-oxide systems that generate electricity onsite, targeting customers constrained by grid availability, reliability requirements, or time-to-power needs.","sells":"Bloom Energy Server systems, installation, operations and maintenance, electricity under legacy arrangements, and solid-oxide electrolyzer systems.","revenueModel":"Equipment and installation revenue, service agreements, electricity revenue, and selected financed or partner-supported project structures.","opportunity":"Power demand from AI infrastructure and other critical loads may value speed, modularity, availability, and onsite generation while grid interconnections remain constrained.","mustGoRight":"Manufacturing must scale with acceptable quality, large orders must convert into profitable deployments, service obligations must remain controlled, and customers must accept fuel and emissions tradeoffs.","editorNote":"Bloom should be judged project by project: backlog quality, customer concentration, product gross margin, installation timing, service costs, fuel economics, and cash collection determine whether demand becomes owner value.","bullTitle":"Time-to-power can be economically valuable","bull":["Modular onsite generation can be installed incrementally without waiting for major transmission expansion.","High availability and load-following characteristics fit critical data-center requirements.","A common solid-oxide platform supports power generation, hydrogen pathways, and manufacturing leverage."],"bearTitle":"Project growth carries concentration and execution risk","bear":["Large customer and partner agreements can make revenue timing uneven.","Natural-gas reliance, tariffs, permitting, and incentive rules affect project economics.","Warranty, service, installation, and manufacturing performance can consume expected equipment margin."],"thesisBreaker":"If large deployments fail to produce durable positive gross profit and operating cash flow after service and warranty obligations, demand growth alone would not validate the thesis.","financialDrivers":[{"label":"Q1 REVENUE","value":"$751.1M · +130%","detail":"Product growth drove the increase; shipments, acceptance, customer and project mix create quarterly variability"},{"label":"GAAP GROSS MARGIN","value":"30.0%","detail":"Manufacturing cost, mix, installation, warranty, service, and pricing determine durability"},{"label":"GAAP OPERATING INCOME","value":"$72.2M","detail":"Evidence of operating leverage, but cash conversion and working capital remain essential"},{"label":"2026 REVENUE GUIDE","value":"$3.4B–$3.8B","detail":"Raised April guidance; delivery, customer concentration, financing, and supply execution must support it"},{"label":"PRODUCT ACCEPTANCE","value":"Revenue timing","detail":"System delivery, installation, customer acceptance, construction, interconnection, and project milestones"},{"label":"OPERATING CASH FLOW","value":"Funding test","detail":"Receivables, inventory, customer deposits, supplier commitments, tax credits, and capex"}],"risks":[{"title":"Customer concentration","level":"High","text":"A limited number of large projects or partners can materially affect reported results and working capital.","signal":"Top-customer share, backlog concentration, and acceptance timing"},{"title":"Fuel and policy exposure","level":"High","text":"Natural-gas availability, interconnection rules, emissions policy, incentives, and tariffs shape customer economics.","signal":"Project cancellations, permitting changes, or incentive reductions"},{"title":"Service and warranty cost","level":"High","text":"Long-lived systems create maintenance and performance obligations after initial installation.","signal":"Service gross margin and warranty accrual trends"},{"title":"Customer and project concentration","level":"High","text":"Large orders and acceptance milestones can concentrate revenue, receivables, execution, and cancellation exposure.","signal":"Top-customer share, backlog, receivables, deposits, project delays, and contract modifications"},{"title":"Policy, fuel, and grid economics","level":"Medium","text":"Tax incentives, tariffs, natural-gas economics, interconnection rules, emissions regulation, and utility pricing affect project returns.","signal":"Tax-credit rules, tariffs, fuel spreads, permitting, utility tariffs, and customer payback"}],"monitor":[{"title":"Data-center project conversion","text":"Track signed projects through permits, interconnection, manufacturing, installation, acceptance, payment, and recurring service.","impact":"BULL CASE"},{"title":"Product and service margins","text":"Separate equipment mix from the installed-base service economics and warranty obligations.","impact":"NEUTRAL"},{"title":"Customer and policy concentration","text":"Measure large-project exposure, tax-credit reliance, utility rules, gas economics, and financing availability.","impact":"BEAR CASE"},{"title":"Bookings-to-cash conversion","text":"Reconcile backlog and shipments with acceptance, receivables, deposits, gross profit, inventory, and operating cash flow.","impact":"NEUTRAL"}],"questions":["How much backlog is firm, financed, permitted, and scheduled?","What lifetime return does Bloom earn after installation, warranty, and service obligations?","Can manufacturing scale preserve margins as project size grows?","How sensitive is customer demand to gas prices, tax policy, and grid interconnection timing?","What portion of backlog has firm pricing, customer funding, and scheduled interconnection?","How sensitive are customer returns to gas prices, tariffs, tax credits, and data-center utilization?"],"competitors":"Electric utilities, gas reciprocating engines, small and combined-cycle turbines, fuel-cell vendors, solar-plus-storage, microgrid integrators, and emerging onsite nuclear systems.","sources":[{"title":"Bloom Energy SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1664703&owner=exclude","excerpt":"Bloom filings describe Energy Server sales and installations, service obligations, customer and supplier exposure, financing, policy, cash, backlog, and risk."},{"title":"Bloom Energy Q1 2026 Results","meta":"Company earnings release · April 28, 2026","href":"https://investor.bloomenergy.com/press-releases/press-release-details/2026/Bloom-Energy-Reports-Record-First-Quarter-2026-Results-and-Raises-Full-Year-2026-Guidance/default.aspx","excerpt":"The official release reports revenue, product growth, margins, operating income, non-GAAP reconciliations, and raised full-year guidance."},{"title":"Bloom Energy SEC Filings","meta":"Company-hosted filing index","href":"https://investor.bloomenergy.com/financials-and-filings/sec-filings/default.aspx","excerpt":"Annual, quarterly, current, ownership, and other filings with direct document formats."},{"title":"Bloom Energy Press Releases","meta":"Company primary materials","href":"https://investor.bloomenergy.com/press-releases/default.aspx","excerpt":"Official customer, partnership, product, financial, and corporate announcements."},{"title":"Bloom Energy Annual Reports","meta":"Company annual filing archive","href":"https://investor.bloomenergy.com/financial-information/annual-reports-and-proxy/default.aspx","excerpt":"Annual reports and proxies provide customer, project, manufacturing, warranty, policy, liquidity, share-count, governance, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investor.bloomenergy.com/press-releases/default.aspx","comparables":[{"name":"FuelCell Energy","ticker":"FCEL","ownership":"Public","relationship":"Stationary fuel-cell technology competitor","valuation":"Compare liquidity and project economics before revenue multiples","financialStatus":"Smaller, loss-making platform with development and financing risk.","sourceUrl":"https://investor.fce.com/"},{"name":"Cummins","ticker":"CMI","ownership":"Public","relationship":"Distributed power, engines, generators, and electrolyzer competitor","valuation":"Diversified industrial earnings reduce direct comparability","financialStatus":"Large profitable power supplier funding lower-carbon technologies from mature operations.","sourceUrl":"https://investor.cummins.com/"},{"name":"Caterpillar","ticker":"CAT","ownership":"Public","relationship":"Distributed generation and data-center power competitor","valuation":"Compare Power & Energy results, not consolidated construction multiples alone","financialStatus":"Highly profitable diversified equipment and power company with dealer and financing scale.","sourceUrl":"https://investors.caterpillar.com/"},{"name":"GE Vernova","ticker":"GEV","ownership":"Public","relationship":"Grid, gas-power, electrification, and energy-services competitor","valuation":"Compare segment backlog, margin, and free cash flow","financialStatus":"Scaled energy-equipment platform spanning Power, Wind, and Electrification.","sourceUrl":"https://www.gevernova.com/investors"},{"name":"Siemens Energy","ticker":"ENR.DE","ownership":"Public","relationship":"Power generation, grid, service, and energy-infrastructure comparable","valuation":"Separate grid, gas services, and wind economics","financialStatus":"Scaled global energy-equipment company with materially broader operations.","sourceUrl":"https://www.siemens-energy.com/global/en/home/investor-relations.html"},{"name":"Generac","ticker":"GNRC","ownership":"Public","relationship":"Distributed generation, storage, and energy-management competitor","valuation":"Compare residential, commercial, and data-center mix","financialStatus":"Profitable distributed-power platform with different fuel-cell and project exposure.","sourceUrl":"https://investors.generac.com/"}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
