INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('META', 'published', '{"ticker":"META","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investor.atmeta.com/investor-news/","description":"Global social, messaging, advertising, AI, mixed-reality, wearable, and developer platforms led by Facebook, Instagram, WhatsApp, Messenger, and Reality Labs.","lede":"Meta monetizes attention and commercial discovery across its Family of Apps while reinvesting heavily in recommendation systems, frontier AI, data centers, messaging, wearables, and Reality Labs. The owner question is whether advertising and engagement gains can continue funding extraordinary infrastructure and experimental spending without weakening per-share cash returns.","sells":"Advertising inventory and performance tools across Facebook, Instagram, Messenger, and third-party placements; business messaging; subscriptions; devices, wearables, virtual-reality hardware, software, and digital content.","revenueModel":"Predominantly advertising priced through auctions and performance objectives, supplemented by business messaging, subscriptions, hardware, software, and digital-content revenue.","opportunity":"Meta can use AI to improve recommendation, creative generation, ad targeting, conversion, messaging, and new consumer devices across billions of daily users.","mustGoRight":"Engagement and advertiser returns must grow, AI infrastructure must improve monetization faster than costs, Reality Labs losses must remain financeable, and privacy, platform, content, and regulatory constraints must not impair advertising signals or distribution.","editorNote":"Q1 2026 revenue rose 33% to $56.31 billion as ad impressions increased 19% and average price per ad increased 12%. Operating cash flow reached $32.23 billion, but capex including finance-lease principal was $19.84 billion and full-year capex guidance rose to $125–145 billion.","bullTitle":"AI improves both engagement and advertising economics","bull":["Family daily active people reached 3.56 billion in Q1 2026, sustaining enormous global distribution.","Ad impressions and average price per ad both grew, showing volume and monetization working together.","Recommendation, creative, messaging, and measurement improvements can increase advertiser return on spend.","Strong operating cash flow and liquidity can fund infrastructure while supporting dividends."],"bearTitle":"A concentrated ad engine is funding several uncertain bets","bear":["Advertising remains the dominant profit source and depends on engagement, signals, advertiser demand, and third-party platforms.","Full-year 2026 capex guidance of $125–145 billion creates substantial utilization, pricing, and technology risk.","Reality Labs and frontier AI may require years of spending before producing durable owner returns.","Privacy, youth safety, content, antitrust, app-store, and geopolitical rules can restrict products and economics."],"thesisBreaker":"The thesis breaks if AI and infrastructure spending continues rising while engagement or ad returns weaken, leaving Family of Apps cash generation unable to fund Reality Labs, frontier research, regulation, and capital returns without materially lower per-share value creation.","financialDrivers":[{"label":"Q1 2026 REVENUE","value":"$56.31B · +33%","detail":"Advertising, foreign exchange, user growth, engagement, pricing, and other revenue"},{"label":"FAMILY DAP","value":"3.56B · +4%","detail":"Daily people across the Family of Apps; geographic access and measurement limitations apply"},{"label":"AD IMPRESSIONS","value":"+19%","detail":"Delivery volume across Family of Apps; mix and surface changes affect comparability"},{"label":"AVERAGE PRICE PER AD","value":"+12%","detail":"Advertiser demand, conversion, format, geography, auction density, and measurement"},{"label":"OPERATING / FREE CASH FLOW","value":"$32.23B / $12.39B","detail":"Q1 cash generation after company-defined capex and finance-lease treatment"},{"label":"2026 CAPEX OUTLOOK","value":"$125–145B","detail":"AI infrastructure, component pricing, data centers, finance leases, and future capacity"}],"risks":[{"title":"Advertising concentration","level":"High","text":"Most revenue depends on advertiser demand, engagement, auction performance, measurement, and commercial outcomes.","signal":"Ad impressions, price per ad, advertiser return, revenue growth, and regional mix"},{"title":"AI infrastructure returns","level":"High","text":"Large data-center, accelerator, energy, and component commitments may outpace monetization or become technologically obsolete.","signal":"Capex, finance leases, depreciation, operating margin, free cash flow, and AI product revenue"},{"title":"Privacy, safety, and regulation","level":"High","text":"Privacy, youth protection, content, competition, elections, and AI rules can create fines, product restrictions, and remediation expense.","signal":"Investigations, settlements, product changes, headcount, and compliance costs"},{"title":"Platform and signal dependence","level":"High","text":"Apple, Google, networks, browsers, standards, and app stores can affect distribution, tracking, payments, and advertising measurement.","signal":"Policy changes, app distribution, signal loss, measurement performance, and developer terms"},{"title":"Reality Labs and experimental allocation","level":"Medium","text":"Mixed reality, wearables, frontier research, and new interfaces can consume substantial capital with uncertain adoption.","signal":"Reality Labs revenue and loss, device adoption, retained users, external partnerships, and spending guidance"}],"monitor":[{"title":"Ad return and engagement","text":"Track impressions, price, conversion, user time, recommendation quality, and advertiser retention together.","impact":"BULL CASE"},{"title":"Capex-to-cash conversion","text":"Compare infrastructure and lease spending with revenue growth, operating margin, free cash flow, and useful-life assumptions.","impact":"NEUTRAL"},{"title":"Business messaging","text":"Measure paid adoption, transaction volume, merchant economics, regional regulation, and cannibalization.","impact":"BULL CASE"},{"title":"Reality Labs and regulatory cost","text":"Require operating milestones and monitor losses, fines, product restrictions, and compliance obligations.","impact":"BEAR CASE"}],"questions":["How much incremental ad revenue is attributable to AI recommendation and creative tools?","What utilization and return thresholds govern the $125–145 billion capex plan?","Can business messaging become a material high-margin revenue stream?","Which third-party platform changes remain the largest threat to measurement and distribution?","What milestones determine continued Reality Labs spending?","How should owners evaluate founder voting control and capital allocation across mature apps and experimental projects?"],"competitors":"Alphabet, ByteDance, Snap, Pinterest, Amazon advertising, Apple, Microsoft, X, messaging platforms, app stores, and mixed-reality and wearable ecosystems.","comparables":[{"name":"Alphabet","ticker":"GOOG","ownership":"Public","relationship":"Digital advertising, AI, video, messaging, cloud, and device competitor","valuation":"Separate Google Services, Cloud, and Other Bets","financialStatus":"Highly profitable advertising and cloud platform with similarly large infrastructure spending.","sourceUrl":"https://abc.xyz/investor/"},{"name":"Snap","ticker":"SNAP","ownership":"Public","relationship":"Social communication, advertising, recommendation, and augmented-reality competitor","valuation":"Compare growth, gross margin, cash burn, and user monetization","financialStatus":"Smaller advertising platform with materially lower scale and profitability.","sourceUrl":"https://investor.snap.com/"},{"name":"Pinterest","ticker":"PINS","ownership":"Public","relationship":"Visual discovery, commerce intent, and advertising competitor","valuation":"Compare engagement, average revenue per user, margin, and cash conversion","financialStatus":"Profitable-at-scale discovery platform with a narrower product surface.","sourceUrl":"https://investor.pinterestinc.com/"},{"name":"Amazon","ticker":"AMZN","ownership":"Public","relationship":"Commerce-linked digital advertising and devices competitor","valuation":"Advertising is embedded inside retail and cloud reporting","financialStatus":"Large profitable advertising business supported by purchase-intent data.","sourceUrl":"https://ir.aboutamazon.com/"},{"name":"ByteDance","ticker":"PRIVATE","ownership":"Private","relationship":"TikTok competes for attention, creators, advertising, discovery, and commerce","valuation":"No continuously observable public valuation","financialStatus":"Private disclosures are incomplete and geopolitical restrictions are material.","sourceUrl":"https://www.bytedance.com/en/"},{"name":"Apple","ticker":"AAPL","ownership":"Public","relationship":"Mobile distribution, privacy policy, devices, wearables, messaging, and mixed-reality competitor","valuation":"Compare ecosystem and services economics rather than advertising alone","financialStatus":"Highly profitable device and services platform that controls important distribution and signals.","sourceUrl":"https://investor.apple.com/"}],"sources":[{"title":"Meta Q1 2026 Results","meta":"Company earnings release · April 29, 2026","href":"https://investor.atmeta.com/investor-news/press-release-details/2026/Meta-Reports-First-Quarter-2026-Results/","excerpt":"The official release reports revenue, users, ad impressions and price, cash flow, capital expenditures, liquidity, headcount, guidance, and risks."},{"title":"Meta SEC Filing Library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1326801&owner=exclude","excerpt":"Annual, quarterly, current, proxy, ownership, debt, and registration filings indexed by the SEC."},{"title":"Meta Financials","meta":"Company financial archive","href":"https://investor.atmeta.com/financials/","excerpt":"Official earnings releases, presentations, transcripts, downloadable statements, SEC filings, and annual reports."},{"title":"Meta Investor Relations","meta":"Company primary materials","href":"https://investor.atmeta.com/","excerpt":"Results, news, events, governance, stock information, SEC filings, and shareholder materials."},{"title":"Meta Q2 2026 Earnings Event","meta":"Company event · July 29, 2026","href":"https://investor.atmeta.com/investor-events/event-details/2026/Q2-2026-Earnings-Call/default.aspx","excerpt":"The official event page provides the webcast and related quarterly materials as published by Meta."},{"title":"Meta Annual Reports","meta":"Company annual filing archive","href":"https://investor.atmeta.com/financials/annual-reports-and-proxy/default.aspx","excerpt":"Annual reports and proxy materials describe the business, segments, governance, capital allocation, competition, privacy, content, and regulatory risks."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
  status = 'published',
  content_json = excluded.content_json,
