INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('LLY', 'published', '{"ticker":"LLY","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investor.lilly.com/news-releases","description":"Research-driven biopharmaceutical company focused on diabetes, obesity, oncology, immunology, and neuroscience.","lede":"Eli Lilly''s value increasingly depends on converting incretin demand into durable global volume while expanding manufacturing and funding the next wave of medicines.","sells":"Prescription medicines including incretin therapies, diabetes products, oncology agents, immunology medicines, and neuroscience treatments.","revenueModel":"Patent-protected pharmaceutical sales through wholesalers, pharmacies, health systems, governments, and managed-care channels, net of rebates and discounts.","opportunity":"Obesity and metabolic disease represent large undertreated markets, while the pipeline can extend growth across new indications and therapeutic areas.","mustGoRight":"Manufacturing must scale, clinical data must support broad use, reimbursement must remain viable, safety must hold, and pipeline productivity must offset future patent losses.","editorNote":"Separate underlying prescription demand from channel inventory and capacity constraints; then test whether manufacturing investment and pricing access produce durable cash returns.","bullTitle":"What can compound owner value","bull":["Incretin therapies address very large diabetes and obesity populations.","Manufacturing investment can unlock constrained demand and global access.","A broad pipeline creates additional indications and new franchises.","Scale and cash generation can fund research without relying on external capital."],"bearTitle":"What can impair the thesis","bear":["Product concentration raises safety, reimbursement, and competitive exposure.","Manufacturing expansion is capital intensive and operationally complex.","Competitors can narrow efficacy, convenience, supply, or pricing advantages.","Government and payer pressure can reduce net prices and access."],"thesisBreaker":"The thesis breaks if incretin safety, efficacy, access, or supply materially disappoints while the broader pipeline fails to replace the resulting growth and cash-flow gap.","financialDrivers":[{"label":"INCRETIN VOLUME","value":"Diabetes and obesity demand","detail":"Prescriptions, patient persistence, indications, geographic access, and supply"},{"label":"NET PRICE","value":"Access economics","detail":"Rebates, payer coverage, government pricing, channel mix, and affordability"},{"label":"MANUFACTURING","value":"Capacity conversion","detail":"Site ramps, yields, device supply, capital spending, and inventory"},{"label":"PIPELINE","value":"Next-wave value","detail":"Probability-adjusted launches, label expansion, differentiation, and patent life"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Clinical and safety","level":"High","text":"Adverse data or post-market findings can restrict large franchises.","signal":"Trial results, label changes, discontinuation, and adverse-event reporting"},{"title":"Reimbursement and pricing","level":"High","text":"Payers and governments can constrain access or net price.","signal":"Coverage criteria, rebates, negotiated prices, and out-of-pocket burden"},{"title":"Manufacturing execution","level":"High","text":"Complex biologic and device supply can delay volume and raise cost.","signal":"Capacity additions, warning letters, shortages, yields, and inventory"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Prescription persistence","text":"Track continuation and real-world outcomes, not only starts.","impact":"BULL CASE"},{"title":"Capacity milestones","text":"Measure announced facilities against validated output and fulfilled demand.","impact":"NEUTRAL"},{"title":"Competitive data","text":"Compare efficacy, safety, dosing, convenience, and payer economics.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["How much demand is durable after normalization of initial supply constraints?","What net-price assumptions support manufacturing returns?","Which pipeline assets can diversify incretin concentration?","What safety signal would change the benefit-risk assessment?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Novo Nordisk, Johnson & Johnson, Merck, AbbVie, AstraZeneca, Pfizer, Amgen, and emerging biotechnology companies.","comparables":[{"name":"Novo Nordisk","ticker":"NVO","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=NVO&owner=exclude"},{"name":"Johnson & Johnson","ticker":"JNJ","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=JNJ&owner=exclude"},{"name":"Merck","ticker":"MRK","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MRK&owner=exclude"},{"name":"AbbVie","ticker":"ABBV","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=ABBV&owner=exclude"},{"name":"AstraZeneca","ticker":"AZN","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AZN&owner=exclude"},{"name":"Amgen","ticker":"AMGN","ownership":"Public","relationship":"Operating and valuation reference for LLY","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LLY.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AMGN&owner=exclude"}],"sources":[{"title":"LLY SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=59478&owner=exclude","excerpt":"The SEC filing record provides LLY''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"LLY annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=59478&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"LLY quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=59478&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"LLY proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=59478&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"LLY investor relations","meta":"Company primary materials","href":"https://investor.lilly.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"LLY official newsroom","meta":"Company announcements","href":"https://investor.lilly.com/news-releases","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
