INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('JPM', 'published', '{"ticker":"JPM","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.jpmorganchase.com/newsroom","description":"Diversified global financial institution spanning consumer and community banking, commercial banking, payments, investment banking, markets, and asset and wealth management.","lede":"JPMorgan combines a low-cost deposit franchise with scale in payments, lending, markets, and asset management. Owners must normalize earnings for rates and credit while judging whether heavy technology and branch investment widens the moat.","sells":"Deposits, credit cards, mortgages, commercial loans, treasury services, payments, investment banking, market-making, custody, and asset and wealth management.","revenueModel":"Net interest income, card and banking fees, investment-banking and markets revenue, payments fees, and asset-management fees, net of credit costs and operating expenses.","opportunity":"Scale, data, distribution, technology investment, and a strong balance sheet can gain share across consumer, commercial, institutional, and wealth markets.","mustGoRight":"Credit underwriting must hold, deposits must remain durable, capital must be sufficient, investments must improve efficiency and share, and regulatory remedies must remain manageable.","editorNote":"Normalize net interest income and credit losses across a rate cycle; then assess whether market-share gains and fee growth support acceptable returns on required capital.","bullTitle":"What can compound owner value","bull":["A broad deposit and payments franchise supports funding and customer relationships.","Investment banking, markets, and asset management diversify spread income.","Technology and distribution spending can deepen scale advantages.","Strong capital and liquidity support resilience and countercyclical investment."],"bearTitle":"What can impair the thesis","bear":["Credit losses can rise after benign periods and overwhelm spread gains.","Deposit repricing and rate cuts can compress net interest income.","Higher capital requirements can reduce returns.","Complexity creates operational, cyber, conduct, and regulatory risk."],"thesisBreaker":"The thesis breaks if credit and operational losses reveal structurally weaker controls while required capital rises and core deposit or fee franchises lose share.","financialDrivers":[{"label":"NET INTEREST INCOME","value":"Rates and deposits","detail":"Deposit balances and beta, loan growth, asset yields, funding mix, and hedge position"},{"label":"CREDIT","value":"Loss normalization","detail":"Delinquencies, charge-offs, reserves, underwriting cohorts, and commercial exposure"},{"label":"FEES","value":"Diversification","detail":"Markets, investment banking, payments, card, custody, and asset-management activity"},{"label":"CAPITAL","value":"Return constraint","detail":"CET1, stress losses, risk-weighted assets, distributions, and regulatory change"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Credit cycle","level":"High","text":"Consumer, commercial, and market exposures can deteriorate together.","signal":"Delinquencies, criticized loans, charge-offs, reserves, and collateral values"},{"title":"Capital and regulation","level":"High","text":"Rules can require more capital or restrict products and distributions.","signal":"CET1 targets, stress tests, enforcement, and proposed rules"},{"title":"Operational and cyber","level":"High","text":"Scale and complexity increase technology, fraud, model, and conduct exposure.","signal":"Outages, losses, remediation spending, and control findings"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Deposit quality","text":"Track noninterest-bearing mix, pricing, retention, and acquisition costs.","impact":"NEUTRAL"},{"title":"Credit cohorts","text":"Follow loss formation by product and vintage before aggregate charge-offs peak.","impact":"BEAR CASE"},{"title":"Share gains and efficiency","text":"Measure whether investment improves revenue share and unit cost.","impact":"BULL CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What is normalized net interest income across a rate cycle?","Which credit portfolios have the most adverse convexity?","How much additional capital could rules require?","Which technology investments have produced measurable returns?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Bank of America, Citigroup, Wells Fargo, Goldman Sachs, Morgan Stanley, U.S. Bancorp, payments networks, and fintech platforms.","comparables":[{"name":"Bank of America","ticker":"BAC","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BAC&owner=exclude"},{"name":"Citigroup","ticker":"C","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=C&owner=exclude"},{"name":"Wells Fargo","ticker":"WFC","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=WFC&owner=exclude"},{"name":"Goldman Sachs","ticker":"GS","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=GS&owner=exclude"},{"name":"Morgan Stanley","ticker":"MS","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MS&owner=exclude"},{"name":"U.S. Bancorp","ticker":"USB","ownership":"Public","relationship":"Operating and valuation reference for JPM","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with JPM.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=USB&owner=exclude"}],"sources":[{"title":"JPM SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=19617&owner=exclude","excerpt":"The SEC filing record provides JPM''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"JPM annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=19617&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"JPM quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=19617&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"JPM proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=19617&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"JPM investor relations","meta":"Company primary materials","href":"https://www.jpmorganchase.com/ir","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"JPM official newsroom","meta":"Company announcements","href":"https://www.jpmorganchase.com/newsroom","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
