INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('WMT', 'published', '{"ticker":"WMT","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://corporate.walmart.com/news","description":"Global omnichannel retailer operating Walmart stores and e-commerce, Sam''s Club, marketplaces, advertising, fulfillment, and related financial services.","lede":"Walmart uses purchasing scale, store density, and logistics to offer low prices while building higher-margin advertising, marketplace, membership, and fulfillment services.","sells":"Groceries, general merchandise, health and wellness products, memberships, advertising, marketplace access, fulfillment, and selected financial and digital services.","revenueModel":"Retail product sales plus membership fees, advertising, marketplace commissions, fulfillment and service fees.","opportunity":"Store density and traffic can lower fulfillment cost and create monetization opportunities beyond merchandise margin.","mustGoRight":"Comparable sales and traffic must remain healthy, inventory must stay disciplined, automation must reduce cost, and higher-margin services must grow without weakening price leadership.","editorNote":"Track gross margin and operating expense alongside sales: the owner thesis depends on mix and productivity converting scale into operating income faster than revenue.","bullTitle":"What can compound owner value","bull":["Scale and grocery frequency support traffic and purchasing power.","Stores serve as distribution nodes for faster omnichannel fulfillment.","Advertising, marketplace, and membership can lift profit mix.","Automation and supply-chain density can improve unit economics."],"bearTitle":"What can impair the thesis","bear":["Retail margins are thin and vulnerable to wage, shrink, freight, and price investment.","Amazon and other platforms compete for digital traffic and sellers.","Inventory errors can force markdowns and working-capital losses.","International and regulatory complexity can dilute returns."],"thesisBreaker":"The thesis breaks if omnichannel growth requires structurally higher fulfillment cost and price investment while higher-margin services fail to offset pressure on core retail returns.","financialDrivers":[{"label":"COMPARABLE SALES","value":"Traffic and ticket","detail":"Units, price, mix, grocery share, and e-commerce contribution"},{"label":"GROSS MARGIN","value":"Mix and markdowns","detail":"Category mix, shrink, freight, sourcing, pricing, and inventory"},{"label":"OPERATING EXPENSE","value":"Productivity","detail":"Wages, automation, delivery, store leverage, and technology"},{"label":"ALTERNATIVE PROFIT","value":"Ads and membership","detail":"Walmart Connect, marketplace, fulfillment, Sam''s Club, and service margins"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Price and cost pressure","level":"High","text":"Low-price positioning can absorb inflation, wages, and competitive investment.","signal":"Price gaps, gross margin, wage expense, and supplier terms"},{"title":"Inventory and shrink","level":"High","text":"Merchandising errors, theft, and obsolescence can impair margin and cash.","signal":"Inventory growth, markdowns, shrink commentary, and working capital"},{"title":"Digital economics","level":"Medium","text":"E-commerce growth may carry higher fulfillment and acquisition cost.","signal":"Contribution margin, delivery density, marketplace mix, and retention"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Operating income versus sales","text":"Look for profit growth exceeding revenue on a sustained basis.","impact":"BULL CASE"},{"title":"Inventory discipline","text":"Compare inventory growth with sales, availability, and markdowns.","impact":"NEUTRAL"},{"title":"Digital contribution margin","text":"Measure ads, marketplace, and fulfillment against delivery cost.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["How profitable is omnichannel retail after all fulfillment costs?","How much operating income comes from advertising and membership?","Can automation lower cost without weakening availability?","What evidence shows durable share gains rather than inflation-driven sales?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Amazon, Costco, Target, Kroger, dollar stores, regional grocers, marketplaces, and specialized retailers.","comparables":[{"name":"Costco Wholesale","ticker":"COST","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=COST&owner=exclude"},{"name":"Target","ticker":"TGT","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TGT&owner=exclude"},{"name":"Amazon","ticker":"AMZN","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AMZN&owner=exclude"},{"name":"Kroger","ticker":"KR","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=KR&owner=exclude"},{"name":"Dollar General","ticker":"DG","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=DG&owner=exclude"},{"name":"BJ''s Wholesale Club","ticker":"BJ","ownership":"Public","relationship":"Operating and valuation reference for WMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BJ&owner=exclude"}],"sources":[{"title":"WMT SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=104169&owner=exclude","excerpt":"The SEC filing record provides WMT''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"WMT annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=104169&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"WMT quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=104169&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"WMT proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=104169&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"WMT investor relations","meta":"Company primary materials","href":"https://stock.walmart.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"WMT official newsroom","meta":"Company announcements","href":"https://corporate.walmart.com/news","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
