INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('MA', 'published', '{"ticker":"MA","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.mastercard.com/news/press/","description":"Global technology company operating payment networks and value-added services across consumers, financial institutions, merchants, businesses, and governments.","lede":"Mastercard monetizes payment and money-movement flows while generally avoiding direct consumer credit risk. The thesis rests on network growth plus services outrunning incentives, regulation, and bypass rails.","sells":"Payment authorization, clearing, settlement, tokenization, fraud and identity tools, data, consulting, open-banking, processing, and money-movement services.","revenueModel":"Domestic assessments, transaction-processing, cross-border, and value-added service revenue, net of rebates and incentives.","opportunity":"Cash conversion, cross-border commerce, account-to-account services, open banking, and cybersecurity broaden the network''s addressable flows.","mustGoRight":"Payment credentials and acceptance must grow, services must add value, incentives must remain productive, and regulation or alternative rails must not undermine economics.","editorNote":"Focus on switched transactions, cross-border mix, service growth, and incentives; reported payment volume alone does not reveal the quality of incremental revenue.","bullTitle":"What can compound owner value","bull":["Global acceptance and issuer connectivity create powerful network effects.","Cash and checks continue to migrate to electronic forms.","Cross-border and commercial flows offer attractive monetization.","Cyber, data, open-banking, and money-movement services expand the platform."],"bearTitle":"What can impair the thesis","bear":["Fee and routing regulation can reduce economics.","Client incentives can absorb gross revenue growth.","Real-time bank rails and wallets can bypass the network.","Cyber events or outages could impair trust and invite remedies."],"thesisBreaker":"The thesis breaks if Mastercard loses transaction flow to alternative rails and must raise incentives while regulatory remedies compress network and cross-border economics.","financialDrivers":[{"label":"GROSS DOLLAR VOLUME","value":"Network flow","detail":"Consumer, commercial, credit, debit, geography, and currency"},{"label":"SWITCHED TRANSACTIONS","value":"Usage density","detail":"Credentials, acceptance, tokenization, routing, and digital mix"},{"label":"CROSS-BORDER","value":"Travel and commerce","detail":"Volume, corridors, pricing, e-commerce, and currency"},{"label":"SERVICES / INCENTIVES","value":"Net monetization","detail":"Cyber, data, processing, contract renewals, and rebates"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Regulatory intervention","level":"High","text":"Interchange, fees, routing, and competition rules can alter economics.","signal":"Legislation, court decisions, settlements, and merchant behavior"},{"title":"Alternative payments","level":"High","text":"Bank rails, wallets, and closed-loop systems can bypass Mastercard.","signal":"Checkout share, account-to-account volume, routing, and pricing"},{"title":"Operational resilience","level":"High","text":"A security breach or outage can harm a critical global network.","signal":"Availability, fraud losses, incidents, remediation, and regulator response"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Net revenue conversion","text":"Compare transaction and volume growth with incentives and services mix.","impact":"NEUTRAL"},{"title":"Cross-border corridors","text":"Separate durable commerce from cyclical travel and currency.","impact":"BULL CASE"},{"title":"Bypass adoption","text":"Measure displacement of Mastercard services by alternative rails.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["Which services are truly independent of card volume?","How much incremental gross revenue is retained after incentives?","Where are real-time rails gaining the most share?","Which regulatory outcome creates the greatest value sensitivity?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Visa, American Express, domestic networks, PayPal, real-time bank systems, wallets, and payment processors.","comparables":[{"name":"Visa","ticker":"V","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=V&owner=exclude"},{"name":"American Express","ticker":"AXP","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AXP&owner=exclude"},{"name":"PayPal","ticker":"PYPL","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PYPL&owner=exclude"},{"name":"Fiserv","ticker":"FI","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=FI&owner=exclude"},{"name":"Fidelity National Information Services","ticker":"FIS","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=FIS&owner=exclude"},{"name":"Global Payments","ticker":"GPN","ownership":"Public","relationship":"Operating and valuation reference for MA","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MA.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=GPN&owner=exclude"}],"sources":[{"title":"MA SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=1141391&owner=exclude","excerpt":"The SEC filing record provides MA''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"MA annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1141391&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"MA quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1141391&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"MA proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=1141391&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"MA investor relations","meta":"Company primary materials","href":"https://investor.mastercard.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"MA official newsroom","meta":"Company announcements","href":"https://www.mastercard.com/news/press/","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
  status = 'published',
