INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('AMAT', 'published', '{"ticker":"AMAT","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://newsroom.appliedmaterials.com/","description":"Semiconductor and display manufacturing-equipment company providing deposition, materials engineering, inspection, packaging, and services.","lede":"Applied Materials earns value by enabling increasingly complex semiconductor structures. Owners must distinguish secular materials intensity from cyclical fab spending and China and export exposure.","sells":"Wafer-fabrication systems, process-control and metrology tools, advanced packaging equipment, display equipment, spare parts, software, and services.","revenueModel":"Capital-equipment sales plus recurring spares, service, and software tied to the installed base.","opportunity":"Gate-all-around transistors, backside power, advanced packaging, new memory architectures, and rising process complexity can increase equipment content per wafer.","mustGoRight":"New products must win critical process steps, customer spending must convert to revenue, service must compound, and export restrictions must remain manageable.","editorNote":"Track share at each technology inflection and installed-base service growth; aggregate wafer-fab spending alone does not reveal competitive position.","bullTitle":"What can compound owner value","bull":["Materials engineering becomes more important as scaling grows complex.","A large installed base supports recurring service revenue.","Advanced packaging expands the served opportunity.","Broad process coverage enables co-optimization across steps."],"bearTitle":"What can impair the thesis","bear":["Semiconductor capital spending is cyclical and customer concentrated.","Export controls can restrict a meaningful market.","ASML, Lam, KLA, TEL, and specialists compete at each process step.","Customers can delay acceptance and create inventory or receivable swings."],"thesisBreaker":"The thesis breaks if Applied loses share at major architecture transitions and service growth cannot offset a prolonged capital-spending downturn or market restrictions.","financialDrivers":[{"label":"WAFER FAB EQUIPMENT","value":"Spending and share","detail":"Logic, foundry, memory, geography, customer concentration, and product mix"},{"label":"TECHNOLOGY INFLECTIONS","value":"Materials intensity","detail":"Gate-all-around, backside power, packaging, memory layers, and qualified steps"},{"label":"SERVICES","value":"Installed-base annuity","detail":"Systems under agreement, utilization, spares, software, and renewal"},{"label":"CHINA / EXPORT","value":"Addressable market","detail":"Rules, licenses, customer mix, compliance, and redirected capacity"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Semicap cycle","level":"High","text":"Customers can sharply reduce or delay equipment spending.","signal":"Capex plans, orders, backlog, utilization, and inventory"},{"title":"Export restrictions","level":"High","text":"Controls can reduce market access or require costly compliance.","signal":"Rule changes, licenses, China revenue, and enforcement"},{"title":"Technology share","level":"High","text":"Failure at a process transition can cause multi-year share loss.","signal":"Customer qualifications, product wins, share, and R&D cadence"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Inflection share","text":"Track qualified process steps and recognized revenue by architecture.","impact":"BULL CASE"},{"title":"Service resilience","text":"Compare recurring service growth with installed-base utilization.","impact":"NEUTRAL"},{"title":"China normalization","text":"Measure sustainable revenue after restrictions and pull-forwards.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["Which architecture transitions create the largest incremental content?","How much China revenue is sustainable under current rules?","What percentage of the installed base is under service agreement?","Where is Applied gaining or losing process-step share?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Lam Research, KLA, ASML, Tokyo Electron, Teradyne, ASM International, and specialist equipment suppliers.","comparables":[{"name":"Lam Research","ticker":"LRCX","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMAT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=LRCX&owner=exclude"},{"name":"KLA","ticker":"KLAC","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMAT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=KLAC&owner=exclude"},{"name":"ASML","ticker":"ASML","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMAT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=ASML&owner=exclude"},{"name":"Teradyne","ticker":"TER","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMAT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TER&owner=exclude"},{"name":"MKS Instruments","ticker":"MKSI","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with AMAT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MKSI&owner=exclude"},{"name":"Advanced Energy Industries","ticker":"AEIS","ownership":"Public","relationship":"Operating and valuation reference for AMAT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","fi