INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('CVX', 'published', '{"ticker":"CVX","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.chevron.com/newsroom","description":"Integrated energy company with upstream oil and gas, LNG, refining, chemicals, marketing, renewable fuels, carbon-management, and related assets.","lede":"Chevron''s owner thesis rests on low-cost resource growth, reliable project delivery, and disciplined distributions through commodity cycles.","sells":"Crude oil, natural gas, LNG, refined products, lubricants, petrochemicals, renewable fuels, and emerging lower-carbon services.","revenueModel":"Commodity and product sales driven by production, benchmark prices, refining and chemical margins, utilization, and fiscal terms.","opportunity":"Permian scale, major international projects, LNG, integration, and technology can support production and free cash flow at competitive breakevens.","mustGoRight":"Tengiz and other projects must ramp, Permian productivity must hold, acquisitions must integrate, and balance-sheet and distributions must remain resilient at mid-cycle prices.","editorNote":"Judge capital projects on sanctioned versus realized cost, schedule, volume, and cash returns, using normalized prices rather than spot conditions.","bullTitle":"What can compound owner value","bull":["A diversified upstream portfolio includes long-life, low-cost resources.","Permian scale and infrastructure can improve productivity.","Integrated refining and chemicals provide additional margin pools.","Balance-sheet capacity supports countercyclical investment and distributions."],"bearTitle":"What can impair the thesis","bear":["Commodity prices dominate short-term cash generation.","Megaprojects and acquisitions carry cost and execution risk.","Reservoir, geopolitical, and contract risks can impair volumes.","Climate policy and liabilities can raise cost or strand capital."],"thesisBreaker":"The thesis breaks if major projects and acquired assets fail to earn adequate mid-cycle returns and capital intensity prevents sustainable per-share cash generation.","financialDrivers":[{"label":"UPSTREAM PRODUCTION","value":"Volume and realization","detail":"Permian, Tengiz, LNG, decline, entitlement, unit cost, and price"},{"label":"DOWNSTREAM","value":"Margin and utilization","detail":"Crack spreads, turnaround, utilization, product demand, and feedstock"},{"label":"PROJECTS / DEALS","value":"Return delivery","detail":"Cost, schedule, startup, plateau, synergies, and breakeven"},{"label":"DISTRIBUTIONS","value":"Cycle resilience","detail":"Dividend, repurchases, debt, asset sales, and cash breakeven"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Commodity cycle","level":"High","text":"Oil, gas, refining, and chemicals can weaken together.","signal":"Realizations, margins, inventories, supply, and demand"},{"title":"Project and acquisition execution","level":"High","text":"Large projects and integrations can miss cost or volume targets.","signal":"Capital revisions, startup timing, synergies, and production"},{"title":"Environmental and geopolitical","level":"High","text":"Policy, litigation, incidents, and host-country actions can impair assets.","signal":"Rules, claims, sanctions, fiscal terms, and provisions"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Tengiz and Permian delivery","text":"Compare production and cash returns with targets and capital spent.","impact":"BULL CASE"},{"title":"Mid-cycle coverage","text":"Test dividend and sustaining capital at normalized prices.","impact":"NEUTRAL"},{"title":"Integration and liabilities","text":"Track acquired performance and contingent obligations.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What mid-cycle prices support the capital and distribution plan?","Are major projects meeting sanctioned economics?","How durable are Permian productivity gains?","Which liabilities have the greatest unrecognized cash sensitivity?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Exxon Mobil, Shell, TotalEnergies, ConocoPhillips, BP, Occidental, national oil companies, and refiners.","comparables":[{"name":"Exxon Mobil","ticker":"XOM","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=XOM&owner=exclude"},{"name":"Shell","ticker":"SHEL","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=SHEL&owner=exclude"},{"name":"TotalEnergies","ticker":"TTE","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TTE&owner=exclude"},{"name":"ConocoPhillips","ticker":"COP","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=COP&owner=exclude"},{"name":"BP","ticker":"BP","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BP&owner=exclude"},{"name":"Occidental Petroleum","ticker":"OXY","ownership":"Public","relationship":"Operating and valuation reference for CVX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CVX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=OXY&owner=exclude"}],"sources":[{"title":"CVX SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=93410&owner=exclude","excerpt":"The SEC filing record provides CVX''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"CVX annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=93410&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"CVX quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=93410&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"CVX proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=93410&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"CVX investor relations","meta":"Company primary materials","href":"https://www.chevron.com/investors","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"CVX official newsroom","meta":"Company announcements","href":"https://www.chevron.com/newsroom","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
