INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('UNH', 'published', '{"ticker":"UNH","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.unitedhealthgroup.com/newsroom.html","description":"Diversified healthcare platform combining UnitedHealthcare insurance benefits with Optum health services, pharmacy care, analytics, and technology.","lede":"UnitedHealth integrates financing and care services at unmatched scale. Owners must judge medical-cost normalization, Medicare economics, Optum transparency, cyber resilience, and regulatory constraints.","sells":"Employer, individual, Medicare, Medicaid, and global health benefits plus pharmacy-benefit, care-delivery, analytics, consulting, and technology services.","revenueModel":"Insurance premiums, service and administrative fees, pharmacy and care revenue, technology fees, and risk-based arrangements, net of medical and operating costs.","opportunity":"Integrated data, care delivery, pharmacy, and benefits can improve outcomes and lower total cost while expanding value-based care.","mustGoRight":"Pricing must keep pace with medical trend, Medicare funding must support acceptable returns, Optum must execute transparently, and cyber and regulatory controls must strengthen.","editorNote":"Reconcile revenue across affiliated businesses and focus on consolidated cash: internal transactions can obscure where economic value and risk ultimately reside.","bullTitle":"What can compound owner value","bull":["Scale and data connect insurance, pharmacy, and care delivery.","Value-based care can align outcomes and cost.","Optum provides diversified service and technology growth.","Recurring premium and service relationships create visibility."],"bearTitle":"What can impair the thesis","bear":["Medical costs can outrun pricing and reserve assumptions.","Medicare and pharmacy regulation can compress economics.","Vertical integration creates antitrust and transparency scrutiny.","Cyber incidents can disrupt critical healthcare operations."],"thesisBreaker":"The thesis breaks if medical and Medicare economics remain structurally inadequate while Optum cannot produce transparent organic cash growth and regulatory or operational remedies constrain integration.","financialDrivers":[{"label":"MEDICAL CARE RATIO","value":"Pricing versus utilization","detail":"Unit cost, utilization, coding, acuity, reserve development, and pricing"},{"label":"MEDICARE ADVANTAGE","value":"Funding and risk","detail":"Rates, star ratings, risk adjustment, benefits, membership, and margin"},{"label":"OPTUM","value":"Services and integration","detail":"Organic growth, care capacity, pharmacy scripts, backlog, and margin"},{"label":"CASH CONVERSION","value":"Consolidated quality","detail":"Operating cash flow, reserves, affiliated transactions, acquisitions, and debt"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Medical-cost mismatch","level":"High","text":"Utilization or unit costs can exceed premiums and reserves.","signal":"Care ratio, prior-period development, utilization, pricing, and guidance"},{"title":"Regulatory and reimbursement","level":"High","text":"Medicare, Medicaid, PBM, and antitrust rules can alter economics.","signal":"Rates, audits, remedies, legislation, and contract changes"},{"title":"Cyber and operational","level":"High","text":"Healthcare infrastructure disruption can cause claims, lost revenue, and remediation.","signal":"Incidents, service restoration, customer retention, and costs"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Pricing versus trend","text":"Compare premium actions with forward medical utilization and cost.","impact":"NEUTRAL"},{"title":"Optum organic evidence","text":"Separate acquisitions and affiliated revenue from external growth and cash.","impact":"BULL CASE"},{"title":"Regulatory remedies","text":"Assess cash and structural effects of each proceeding.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What normalized care ratio supports current pricing?","How much Optum growth is external and organic?","Which Medicare assumptions are most sensitive to policy?","What operational control changes followed major cyber incidents?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Elevance Health, CVS Health and Aetna, Cigna, Humana, Centene, Molina, hospital systems, physician groups, and pharmacy-benefit managers.","comparables":[{"name":"Elevance Health","ticker":"ELV","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=ELV&owner=exclude"},{"name":"CVS Health","ticker":"CVS","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=CVS&owner=exclude"},{"name":"Cigna","ticker":"CI","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=CI&owner=exclude"},{"name":"Humana","ticker":"HUM","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=HUM&owner=exclude"},{"name":"Centene","ticker":"CNC","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=CNC&owner=exclude"},{"name":"Molina Healthcare","ticker":"MOH","ownership":"Public","relationship":"Operating and valuation reference for UNH","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UNH.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MOH&owner=exclude"}],"sources":[{"title":"UNH SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=731766&owner=exclude","excerpt":"The SEC filing record provides UNH''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"UNH annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=731766&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"UNH quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=731766&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"UNH proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=731766&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"UNH investor relations","meta":"Company primary materials","href":"https://www.unitedhealthgroup.com/investors.html","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"UNH official newsroom","meta":"Company announcements","href":"https://www.unitedhealthgroup.com/newsroom.html","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
