INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('KO', 'published', '{"ticker":"KO","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.coca-colacompany.com/media-center","description":"Global beverage company owning brands and selling concentrates, syrups, finished beverages, and marketing support through a worldwide bottling system.","lede":"Coca-Cola''s economics come from brands, concentrate margins, and bottler distribution. Owners must separate unit volume from price, mix, currency, acquisitions, and refranchising.","sells":"Sparkling soft drinks, water, sports drinks, juice, dairy, plant-based beverages, coffee, tea, energy drinks, concentrates, syrups, and finished products.","revenueModel":"Concentrate and syrup sales to bottlers plus finished-product sales and other beverage partnerships, with revenue shaped by price, mix, volume, and currency.","opportunity":"Global distribution, brand investment, package innovation, and expansion across beverage categories can increase servings and revenue per occasion.","mustGoRight":"Brands must sustain consumer relevance, pricing must not damage volume, bottlers must invest and execute, and input and currency pressure must be managed.","editorNote":"Use organic revenue decomposition and concentrate shipment versus unit-case volume to distinguish economic growth from timing, bottler inventory, and refranchising.","bullTitle":"What can compound owner value","bull":["Global brands and distribution create durable consumer reach.","An asset-lighter concentrate model supports strong margins.","Pricing, package, and channel mix can grow revenue per serving.","A broad portfolio extends beyond traditional soda."],"bearTitle":"What can impair the thesis","bear":["Persistent pricing can weaken affordability and volume.","Health regulation and consumer preferences can pressure categories.","Currency and emerging-market volatility affect reported results.","Bottler health and execution sit partly outside company control."],"thesisBreaker":"The thesis breaks if sustained volume and brand relevance decline while pricing and mix can no longer offset inflation, currency, and bottler investment needs.","financialDrivers":[{"label":"UNIT CASE VOLUME","value":"Consumer demand","detail":"Region, category, channel, affordability, and share"},{"label":"PRICE / MIX","value":"Revenue per case","detail":"Pricing, package, channel, geography, promotions, and inflation"},{"label":"CONCENTRATE ECONOMICS","value":"Asset-light margin","detail":"Shipment timing, bottler inventory, incidence pricing, and refranchising"},{"label":"CURRENCY / INPUT","value":"Reported conversion","detail":"Foreign exchange, sweeteners, packaging, freight, hedging, and bottler pass-through"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Consumer and health shifts","level":"High","text":"Preferences and regulation can reduce demand for major categories.","signal":"Volume, market share, sugar taxes, labels, and reformulation"},{"title":"Pricing elasticity","level":"Medium","text":"Price increases can pressure affordability and occasions.","signal":"Volume, package mix, promotions, and emerging-market performance"},{"title":"Bottling system","level":"Medium","text":"Bottler financial health and execution affect availability and brand investment.","signal":"Bottler capex, leverage, service levels, and territory performance"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Volume versus price","text":"Require balanced organic growth rather than price-only expansion.","impact":"BULL CASE"},{"title":"Affordability","text":"Track package architecture and volume in lower-income markets.","impact":"NEUTRAL"},{"title":"Brand and regulation","text":"Watch share, consumption trends, and policy by category.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["How much organic growth is volume versus price and mix?","Where is affordability limiting demand?","Are bottlers earning returns sufficient to reinvest?","Which categories can diversify traditional sparkling beverages?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"PepsiCo, Keurig Dr Pepper, Monster Beverage, local bottlers, private labels, coffee chains, water, and alcoholic beverages.","comparables":[{"name":"PepsiCo","ticker":"PEP","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PEP&owner=exclude"},{"name":"Keurig Dr Pepper","ticker":"KDP","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=KDP&owner=exclude"},{"name":"Monster Beverage","ticker":"MNST","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MNST&owner=exclude"},{"name":"Coca-Cola Europacific Partners","ticker":"CCEP","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=CCEP&owner=exclude"},{"name":"Coca-Cola Consolidated","ticker":"COKE","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=COKE&owner=exclude"},{"name":"Primo Brands","ticker":"PRMB","ownership":"Public","relationship":"Operating and valuation reference for KO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with KO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PRMB&owner=exclude"}],"sources":[{"title":"KO SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=21344&owner=exclude","excerpt":"The SEC filing record provides KO''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"KO annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=21344&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"KO quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=21344&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"KO proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=21344&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"KO investor relations","meta":"Company primary materials","href":"https://investors.coca-colacompany.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"KO official newsroom","meta":"Company announcements","href":"https://www.coca-colacompany.com/media-center","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
