INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('LRCX', 'published', '{"ticker":"LRCX","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://newsroom.lamresearch.com/","description":"Semiconductor manufacturing-equipment company specializing in etch, deposition, clean, advanced packaging, and installed-base services.","lede":"Lam Research benefits as memory and logic structures require more complex etch and deposition. Owners must distinguish content gains from memory-cycle spending and export-driven volatility.","sells":"Plasma etch, thin-film deposition, clean and related wafer-fabrication systems, advanced packaging tools, spares, upgrades, and services.","revenueModel":"Capital-equipment sales plus recurring customer-support revenue tied to the installed base and fab utilization.","opportunity":"Higher NAND layers, DRAM scaling, gate-all-around, backside power, and advanced packaging increase the number and difficulty of critical process steps.","mustGoRight":"Lam must win process steps at new architectures, customers must sustain investment, service must remain resilient, and export controls must not structurally reduce opportunity.","editorNote":"Map Lam content per wafer at each architecture transition; broad wafer-fab spending and memory prices are insufficient to prove company-specific share gains.","bullTitle":"What can compound owner value","bull":["Etch and deposition intensity rises with three-dimensional structures.","Memory and advanced packaging create substantial process complexity.","A large installed base supports recurring service and upgrade revenue.","Deep customer process integration can create switching costs."],"bearTitle":"What can impair the thesis","bear":["Memory capital spending is highly cyclical.","Export restrictions can remove or defer market access.","Technology transitions can shift share to competitors.","Customer concentration increases negotiation and timing risk."],"thesisBreaker":"The thesis breaks if Lam loses critical etch and deposition share at major architecture transitions and services cannot offset a memory-led spending downturn and market restrictions.","financialDrivers":[{"label":"MEMORY WFE","value":"NAND and DRAM spending","detail":"Layer count, node transitions, utilization, capex, and customer mix"},{"label":"FOUNDRY / LOGIC","value":"Architecture content","detail":"Gate-all-around, backside power, packaging, share, and qualification"},{"label":"CUSTOMER SUPPORT","value":"Installed-base annuity","detail":"Chamber count, utilization, spares, upgrades, service agreements, and pricing"},{"label":"CHINA / EXPORT","value":"Addressable demand","detail":"Rules, licenses, revenue mix, customer pull-forward, and compliance"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Memory cycle","level":"High","text":"Memory customers can sharply change capital spending.","signal":"Pricing, inventory, utilization, capex, orders, and backlog"},{"title":"Technology share","level":"High","text":"Lost process positions can persist across several product generations.","signal":"Qualifications, process wins, share, and R&D timing"},{"title":"Export restrictions","level":"High","text":"Controls can limit shipments or service to important customers.","signal":"Rule changes, licenses, China mix, and enforcement"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Content per wafer","text":"Measure process-step wins and recognized revenue at new nodes.","impact":"BULL CASE"},{"title":"Service resilience","text":"Compare customer-support revenue with utilization and installed base.","impact":"NEUTRAL"},{"title":"Memory supply cycle","text":"Watch customer capex relative to bit-demand growth.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["Which transitions create the largest incremental Lam content?","How resilient is service revenue at low utilization?","What China revenue is sustainable under current controls?","Where is Lam gaining or losing process-step share?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Applied Materials, Tokyo Electron, KLA, ASML, ASM International, and specialist process-equipment suppliers.","comparables":[{"name":"Applied Materials","ticker":"AMAT","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AMAT&owner=exclude"},{"name":"KLA","ticker":"KLAC","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=KLAC&owner=exclude"},{"name":"ASML","ticker":"ASML","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=ASML&owner=exclude"},{"name":"Teradyne","ticker":"TER","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TER&owner=exclude"},{"name":"MKS Instruments","ticker":"MKSI","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=MKSI&owner=exclude"},{"name":"Advanced Energy Industries","ticker":"AEIS","ownership":"Public","relationship":"Operating and valuation reference for LRCX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LRCX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AEIS&owner=exclude"}],"sources":[{"title":"LRCX SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=707549&owner=exclude","excerpt":"The SEC filing record provides LRCX''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"LRCX annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=707549&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"LRCX quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=707549&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"LRCX proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=707549&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"LRCX investor relations","meta":"Company primary materials","href":"https://investor.lamresearch.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"LRCX official newsroom","meta":"Company announcements","href":"https://newsroom.lamresearch.com/","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
