INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('GE', 'published', '{"ticker":"GE","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://www.geaerospace.com/news","description":"Commercial and defense aerospace company centered on aircraft engines, propulsion systems, spare parts, maintenance, repair, and overhaul services.","lede":"GE Aerospace''s installed engine base creates decades of service demand, but owner value depends on fleet utilization, shop-visit execution, supply-chain throughput, and disciplined investment in new propulsion.","sells":"Commercial and military aircraft engines, propulsion systems, components, spare parts, maintenance, repair, overhaul, and digital fleet services.","revenueModel":"Original-equipment engine sales plus long-duration, often higher-margin aftermarket parts and service revenue linked to installed engines and flight activity.","opportunity":"A growing installed base, rising departures, aging fleets, defense demand, and service agreements can support long-duration aftermarket cash flow.","mustGoRight":"Suppliers and shops must increase output, reliability and safety must hold, service obligations must be accurately estimated, and next-generation engine investment must earn adequate returns.","editorNote":"The owner model should connect engine deliveries to the future installed base and then to shop visits, spare-parts content, contract margins, working capital, and cash over decades.","bullTitle":"What can compound owner value","bull":["A large installed base creates long-duration aftermarket demand.","Air travel and fleet utilization support shop visits and spare parts.","Engine technology and certification create high barriers to entry.","Defense programs diversify commercial aviation exposure."],"bearTitle":"What can impair the thesis","bear":["Supply constraints can delay deliveries and service revenue.","Safety or reliability issues can create large technical and financial liabilities.","Long-term service contracts depend on uncertain future costs.","New engine programs require heavy R&D and can have weak initial economics."],"thesisBreaker":"The thesis breaks if reliability or supply problems impair the installed-base franchise and service-contract costs rise faster than pricing while new programs consume cash without durable share.","financialDrivers":[{"label":"COMMERCIAL ENGINES","value":"Deliveries and installed base","detail":"Shipsets, mix, pricing, backlog, customer concentration, and concessions"},{"label":"SERVICES","value":"Shop-visit economics","detail":"Departures, utilization, visit timing, spare content, pricing, and contract margin"},{"label":"SUPPLY CHAIN","value":"Throughput constraint","detail":"Castings, forgings, labor, supplier health, inventory, and on-time delivery"},{"label":"DEFENSE / R&D","value":"Program and future platform","detail":"Funding, deliveries, milestones, development cost, and next-generation selection"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Safety and reliability","level":"High","text":"Technical issues can ground fleets or require costly remediation.","signal":"Directives, removals, inspection intervals, warranty, and customer compensation"},{"title":"Supply-chain execution","level":"High","text":"Specialized suppliers can constrain engines and shop visits.","signal":"Past-due material, lead times, output, inventory, and supplier financing"},{"title":"Contract estimates","level":"High","text":"Long-term service margins depend on utilization, price, and future cost.","signal":"Contract adjustments, loss provisions, shop-visit cost, and assumptions"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Shop-visit throughput","text":"Track visits, turnaround time, spare content, and service cash.","impact":"BULL CASE"},{"title":"Reliability evidence","text":"Monitor directives, removals, warranty, and compensation.","impact":"BEAR CASE"},{"title":"Working capital","text":"Reconcile backlog and advances with inventory and supplier commitments.","impact":"NEUTRAL"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What limits shop-visit throughput today?","How sensitive are service margins to utilization and material cost?","Which reliability assumption has the largest contract impact?","What return threshold governs next-generation engine investment?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"RTX and Pratt & Whitney, Safran and CFM partnerships, Rolls-Royce, Boeing, TransDigm, Howmet, and defense propulsion suppliers.","comparables":[{"name":"RTX","ticker":"RTX","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=RTX&owner=exclude"},{"name":"Boeing","ticker":"BA","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BA&owner=exclude"},{"name":"TransDigm Group","ticker":"TDG","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TDG&owner=exclude"},{"name":"Howmet Aerospace","ticker":"HWM","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=HWM&owner=exclude"},{"name":"Hexcel","ticker":"HXL","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=HXL&owner=exclude"},{"name":"Woodward","ticker":"WWD","ownership":"Public","relationship":"Operating and valuation reference for GE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with GE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=WWD&owner=exclude"}],"sources":[{"title":"GE SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=40545&owner=exclude","excerpt":"The SEC filing record provides GE''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"GE annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=40545&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"GE quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=40545&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"GE proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=40545&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"GE investor relations","meta":"Company primary materials","href":"https://www.geaerospace.com/investor-relations","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"GE official newsroom","meta":"Company announcements","href":"https://www.geaerospace.com/news","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
  status = 'published',
