INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('STX', 'published', '{"ticker":"STX","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.seagate.com/news/","description":"Data-storage company designing hard-disk drives and related storage systems for cloud, enterprise, video, and consumer markets.","lede":"SEAGATE TECHNOLOGY HOLDINGS PLC earns owner value through storage-device and system sales to hyperscalers, oems, distributors, retailers, and enterprise customers. The three questions that matter most are cloud demand, drive capacity, units, pricing, and customer qualification, yield, reliability, capacity points, cost per terabyte, and customer adoption, inventory, factory utilization, lead times, price per terabyte, and competitor discipline.","sells":"Nearline, enterprise, client, video, and consumer hard drives plus storage systems and services.","revenueModel":"Storage-device and system sales to hyperscalers, OEMs, distributors, retailers, and enterprise customers.","opportunity":"HAMR adoption, capacity growth, disciplined industry supply, and cloud storage demand can increase exabytes and margin.","mustGoRight":"HAMR yields and reliability must scale, hyperscaler qualification must convert, and industry supply discipline must persist.","editorNote":"Treat the claimed advantage—a concentrated industry, areal-density engineering, and high-capacity nearline products can support improving economics as cloud data grows.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A concentrated industry, areal-density engineering, and high-capacity nearline products can support improving economics as cloud data grows.","HAMR adoption, capacity growth, disciplined industry supply, and cloud storage demand can increase exabytes and margin.","Visible progress in nearline exabytes and hamr ramp can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Customer concentration and cycle can weaken the owner outcome; monitor hyperscaler capex, inventory, order timing, and pricing.","Technology execution can weaken the owner outcome; monitor hamr yields, reliability, qualification, roadmap, and warranty.","Flash substitution can weaken the owner outcome; monitor nand cost, total cost of ownership, workload fit, and adoption.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if HAMR scale slips and flash substitution or customer insourcing structurally reduces nearline demand and pricing.","financialDrivers":[{"label":"NEARLINE EXABYTES","value":"Primary owner KPI","detail":"cloud demand, drive capacity, units, pricing, and customer qualification"},{"label":"HAMR RAMP","value":"Primary owner KPI","detail":"yield, reliability, capacity points, cost per terabyte, and customer adoption"},{"label":"INDUSTRY SUPPLY","value":"Primary owner KPI","detail":"inventory, factory utilization, lead times, price per terabyte, and competitor discipline"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Customer concentration and cycle","level":"High","text":"Customer concentration and cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"hyperscaler capex, inventory, order timing, and pricing"},{"title":"Technology execution","level":"High","text":"Technology execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"HAMR yields, reliability, qualification, roadmap, and warranty"},{"title":"Flash substitution","level":"High","text":"Flash substitution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"NAND cost, total cost of ownership, workload fit, and adoption"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"NEARLINE EXABYTES","text":"Track cloud demand, drive capacity, units, pricing, and customer qualification and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"HAMR RAMP","text":"Track yield, reliability, capacity points, cost per terabyte, and customer adoption and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"INDUSTRY SUPPLY","text":"Track inventory, factory utilization, lead times, price per terabyte, and competitor discipline and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies nearline exabytes?","What would cause hamr ramp to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in industry supply?","Where does SEAGATE TECHNOLOGY HOLDINGS PLC have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"WESTERN DIGITAL CORP, Sandisk Corp, MICRON TECHNOLOGY INC, PSTG, NetApp, Inc., Dell Technologies Inc.","comparables":[{"name":"WESTERN DIGITAL CORP","ticker":"WDC","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000106040&owner=exclude"},{"name":"Sandisk Corp","ticker":"SNDK","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0002023554&owner=exclude"},{"name":"MICRON TECHNOLOGY INC","ticker":"MU","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000723125&owner=exclude"},{"name":"PSTG","ticker":"PSTG","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PSTG&owner=exclude"},{"name":"NetApp, Inc.","ticker":"NTAP","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001002047&owner=exclude"},{"name":"Dell Technologies Inc.","ticker":"DELL","ownership":"Public","relationship":"Operating and valuation reference for STX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with STX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001571996&owner=exclude"}],"sources":[{"title":"STX SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001137789&owner=exclude","excerpt":"Seagate Technology Holdings plc filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"STX annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001137789&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"STX quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001137789&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"STX proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001137789&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"STX investor relations","meta":"Company primary materials","href":"https://investors.seagate.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"STX official newsroom","meta":"Company announcements","href":"https://www.seagate.com/news/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
