INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('VZ', 'published', '{"ticker":"VZ","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.verizon.com/about/news","description":"U.S. communications company providing wireless, broadband, private-network, and enterprise connectivity.","lede":"VERIZON COMMUNICATIONS Inc. earns owner value through recurring service subscriptions, equipment sales, wholesale access, and enterprise connectivity contracts. The three questions that matter most are postpaid phone adds, churn, pricing, plan mix, and promotional cost, fixed-wireless and fiber additions, capacity, pricing, and convergence, service ebitda, handset working capital, capex, spectrum, interest, and dividends.","sells":"Consumer and business wireless service, devices, fixed wireless, fiber broadband, network services, security, and IoT connectivity.","revenueModel":"Recurring service subscriptions, equipment sales, wholesale access, and enterprise connectivity contracts.","opportunity":"Fixed wireless, fiber expansion, premium plans, private networks, and cost discipline can stabilize growth.","mustGoRight":"Subscriber economics must improve without excessive promotions, network investment must earn returns, and leverage must remain controlled.","editorNote":"Treat the claimed advantage—nationwide spectrum, network quality, distribution, and converged wireless-broadband relationships can support retention and cash flow.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Nationwide spectrum, network quality, distribution, and converged wireless-broadband relationships can support retention and cash flow.","Fixed wireless, fiber expansion, premium plans, private networks, and cost discipline can stabilize growth.","Visible progress in wireless service and broadband can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Wireless competition can weaken the owner outcome; monitor churn, promotions, price, gross additions, and share.","Network capital intensity can weaken the owner outcome; monitor capex, spectrum, densification, fixed-wireless capacity, and returns.","Leverage and legacy liabilities can weaken the owner outcome; monitor debt, interest, lead-sheathed cable claims, pension, and litigation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if service share and pricing weaken while capital requirements and debt prevent sustainable free cash flow growth.","financialDrivers":[{"label":"WIRELESS SERVICE","value":"Primary owner KPI","detail":"postpaid phone adds, churn, pricing, plan mix, and promotional cost"},{"label":"BROADBAND","value":"Primary owner KPI","detail":"fixed-wireless and fiber additions, capacity, pricing, and convergence"},{"label":"FREE CASH FLOW","value":"Primary owner KPI","detail":"service EBITDA, handset working capital, capex, spectrum, interest, and dividends"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Wireless competition","level":"High","text":"Wireless competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"churn, promotions, price, gross additions, and share"},{"title":"Network capital intensity","level":"High","text":"Network capital intensity can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"capex, spectrum, densification, fixed-wireless capacity, and returns"},{"title":"Leverage and legacy liabilities","level":"High","text":"Leverage and legacy liabilities can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"debt, interest, lead-sheathed cable claims, pension, and litigation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"WIRELESS SERVICE","text":"Track postpaid phone adds, churn, pricing, plan mix, and promotional cost and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"BROADBAND","text":"Track fixed-wireless and fiber additions, capacity, pricing, and convergence and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"FREE CASH FLOW","text":"Track service ebitda, handset working capital, capex, spectrum, interest, and dividends and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies wireless service?","What would cause broadband to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in free cash flow?","Where does VERIZON COMMUNICATIONS Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"AT&T INC., T-Mobile US, Inc., CHARTER COMMUNICATIONS, INC., COMCAST CORP, Lumen Technologies, Inc., DTEGY","comparables":[{"name":"AT&T INC.","ticker":"T","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000732717&owner=exclude"},{"name":"T-Mobile US, Inc.","ticker":"TMUS","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001283699&owner=exclude"},{"name":"CHARTER COMMUNICATIONS, INC.","ticker":"CHTR","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001091667&owner=exclude"},{"name":"COMCAST CORP","ticker":"CMCSA","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001166691&owner=exclude"},{"name":"Lumen Technologies, Inc.","ticker":"LUMN","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000018926&owner=exclude"},{"name":"DTEGY","ticker":"DTEGY","ownership":"Public","relationship":"Operating and valuation reference for VZ","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with VZ.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=DTEGY&owner=exclude"}],"sources":[{"title":"VZ SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000732712&owner=exclude","excerpt":"VERIZON COMMUNICATIONS INC filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"VZ annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732712&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"VZ quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732712&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"VZ proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732712&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"VZ investor relations","meta":"Company primary materials","href":"https://www.verizon.com/about/investors","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"VZ official newsroom","meta":"Company announcements","href":"https://www.verizon.com/about/news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
