INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('WDC', 'published', '{"ticker":"WDC","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.westerndigital.com/company/newsroom","description":"Data-storage company focused on hard-disk-drive technologies and high-capacity storage products following separation of its flash business.","lede":"WESTERN DIGITAL Corp. earns owner value through storage-device sales to hyperscalers, oems, distributors, retailers, and enterprise customers. The three questions that matter most are cloud capex, drive capacity, units, price per terabyte, and share, areal density, yield, reliability, qualification, and cost, standalone cost, working capital, capital allocation, and free cash flow.","sells":"Nearline, enterprise, client, surveillance, gaming, and consumer hard drives and related storage products.","revenueModel":"Storage-device sales to hyperscalers, OEMs, distributors, retailers, and enterprise customers.","opportunity":"Cloud exabyte growth, higher drive capacities, disciplined supply, and technology transitions can improve price and margin.","mustGoRight":"Technology ramps and customer qualifications must execute, separation costs must normalize, and industry supply must remain disciplined.","editorNote":"Treat the claimed advantage—a concentrated hdd industry, areal-density roadmaps, and cloud-customer qualifications can support high-capacity storage economics.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A concentrated HDD industry, areal-density roadmaps, and cloud-customer qualifications can support high-capacity storage economics.","Cloud exabyte growth, higher drive capacities, disciplined supply, and technology transitions can improve price and margin.","Visible progress in nearline exabytes and technology roadmap can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Customer concentration and cycle can weaken the owner outcome; monitor hyperscaler demand, inventory, qualifications, and order timing.","Technology execution can weaken the owner outcome; monitor roadmap, yields, reliability, warranty, and competitor capacity.","Storage substitution can weaken the owner outcome; monitor flash cost curves, workload fit, total cost, and adoption.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if nearline HDD demand is structurally displaced and technology execution fails to sustain competitive cost per terabyte.","financialDrivers":[{"label":"NEARLINE EXABYTES","value":"Primary owner KPI","detail":"cloud capex, drive capacity, units, price per terabyte, and share"},{"label":"TECHNOLOGY ROADMAP","value":"Primary owner KPI","detail":"areal density, yield, reliability, qualification, and cost"},{"label":"POST-SEPARATION ECONOMICS","value":"Primary owner KPI","detail":"standalone cost, working capital, capital allocation, and free cash flow"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Customer concentration and cycle","level":"High","text":"Customer concentration and cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"hyperscaler demand, inventory, qualifications, and order timing"},{"title":"Technology execution","level":"High","text":"Technology execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"roadmap, yields, reliability, warranty, and competitor capacity"},{"title":"Storage substitution","level":"High","text":"Storage substitution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"flash cost curves, workload fit, total cost, and adoption"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"NEARLINE EXABYTES","text":"Track cloud capex, drive capacity, units, price per terabyte, and share and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"TECHNOLOGY ROADMAP","text":"Track areal density, yield, reliability, qualification, and cost and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"POST-SEPARATION ECONOMICS","text":"Track standalone cost, working capital, capital allocation, and free cash flow and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies nearline exabytes?","What would cause technology roadmap to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in post-separation economics?","Where does WESTERN DIGITAL Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Seagate Technology Holdings plc, Sandisk Corp, MICRON TECHNOLOGY INC, PSTG, NetApp, Inc., Dell Technologies Inc.","comparables":[{"name":"Seagate Technology Holdings plc","ticker":"STX","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001137789&owner=exclude"},{"name":"Sandisk Corp","ticker":"SNDK","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0002023554&owner=exclude"},{"name":"MICRON TECHNOLOGY INC","ticker":"MU","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000723125&owner=exclude"},{"name":"PSTG","ticker":"PSTG","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PSTG&owner=exclude"},{"name":"NetApp, Inc.","ticker":"NTAP","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001002047&owner=exclude"},{"name":"Dell Technologies Inc.","ticker":"DELL","ownership":"Public","relationship":"Operating and valuation reference for WDC","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with WDC.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001571996&owner=exclude"}],"sources":[{"title":"WDC SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000106040&owner=exclude","excerpt":"WESTERN DIGITAL CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"WDC annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000106040&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"WDC quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000106040&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"WDC proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000106040&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"WDC investor relations","meta":"Company primary materials","href":"https://investor.wdc.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"WDC official newsroom","meta":"Company announcements","href":"https://www.westerndigital.com/company/newsroom","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT(ticker) DO UPDATE SET
