INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('ABT', 'published', '{"ticker":"ABT","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.abbott.com/corpnewsroom.html","description":"Diversified health-care company spanning medical devices, diagnostics, nutrition, and established pharmaceuticals.","lede":"ABBOTT LABORATORIES earns owner value through device and instrument sales, recurring sensors and consumables, diagnostic tests, nutrition products, and pharmaceutical sales. The three questions that matter most are sensor users, pricing, reimbursement, geography, and competition, procedure volumes, share, launches, clinical data, and mix, installed base, test volume, base demand, market share, and margin.","sells":"Diabetes sensors, cardiovascular devices, diagnostics systems and tests, infant and adult nutrition, and branded generics.","revenueModel":"Device and instrument sales, recurring sensors and consumables, diagnostic tests, nutrition products, and pharmaceutical sales.","opportunity":"Continuous glucose monitoring, structural heart, electrophysiology, diagnostics automation, and emerging markets can drive growth.","mustGoRight":"Device innovation and reimbursement must sustain adoption, quality must remain high, and nutrition and diagnostics must stabilize.","editorNote":"Treat the claimed advantage—large installed bases, clinical evidence, distribution, and diversified health-care exposure can support recurring demand.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Large installed bases, clinical evidence, distribution, and diversified health-care exposure can support recurring demand.","Continuous glucose monitoring, structural heart, electrophysiology, diagnostics automation, and emerging markets can drive growth.","Visible progress in diabetes care and medical devices can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Product quality and safety can weaken the owner outcome; monitor recalls, warning letters, trial data, claims, and remediation.","Reimbursement and competition can weaken the owner outcome; monitor coverage, pricing, tenders, share, and new technology.","Supply and execution can weaken the owner outcome; monitor manufacturing, shortages, launches, inventory, and service levels.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if key device franchises lose clinical or technological relevance and recurring consumables fail to sustain returns.","financialDrivers":[{"label":"DIABETES CARE","value":"Primary owner KPI","detail":"sensor users, pricing, reimbursement, geography, and competition"},{"label":"MEDICAL DEVICES","value":"Primary owner KPI","detail":"procedure volumes, share, launches, clinical data, and mix"},{"label":"DIAGNOSTICS & NUTRITION","value":"Primary owner KPI","detail":"installed base, test volume, base demand, market share, and margin"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Product quality and safety","level":"High","text":"Product quality and safety can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"recalls, warning letters, trial data, claims, and remediation"},{"title":"Reimbursement and competition","level":"High","text":"Reimbursement and competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"coverage, pricing, tenders, share, and new technology"},{"title":"Supply and execution","level":"High","text":"Supply and execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"manufacturing, shortages, launches, inventory, and service levels"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"DIABETES CARE","text":"Track sensor users, pricing, reimbursement, geography, and competition and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"MEDICAL DEVICES","text":"Track procedure volumes, share, launches, clinical data, and mix and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"DIAGNOSTICS & NUTRITION","text":"Track installed base, test volume, base demand, market share, and margin and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies diabetes care?","What would cause medical devices to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in diagnostics & nutrition?","Where does ABBOTT LABORATORIES have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Medtronic plc, STRYKER CORP, BOSTON SCIENTIFIC CORP, BECTON DICKINSON & CO, THERMO FISHER SCIENTIFIC INC., JOHNSON & JOHNSON","comparables":[{"name":"Medtronic plc","ticker":"MDT","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001613103&owner=exclude"},{"name":"STRYKER CORP","ticker":"SYK","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000310764&owner=exclude"},{"name":"BOSTON SCIENTIFIC CORP","ticker":"BSX","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000885725&owner=exclude"},{"name":"BECTON DICKINSON & CO","ticker":"BDX","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000010795&owner=exclude"},{"name":"THERMO FISHER SCIENTIFIC INC.","ticker":"TMO","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000097745&owner=exclude"},{"name":"JOHNSON & JOHNSON","ticker":"JNJ","ownership":"Public","relationship":"Operating and valuation reference for ABT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ABT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000200406&owner=exclude"}],"sources":[{"title":"ABT SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000001800&owner=exclude","excerpt":"ABBOTT LABORATORIES filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"ABT annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000001800&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"ABT quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000001800&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"ABT proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000001800&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"ABT investor relations","meta":"Company primary materials","href":"https://www.abbottinvestor.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"ABT official newsroom","meta":"Company announcements","href":"https://www.abbott.com/corpnewsroom.html","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
