INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('SCHW', 'published', '{"ticker":"SCHW","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://pressroom.aboutschwab.com/","description":"Brokerage, wealth, custody, banking, and asset-management platform serving retail investors and independent advisers.","lede":"CHARLES SCHWAB Corp. earns owner value through net interest revenue, asset-management and administration fees, trading revenue, advice fees, and bank-related income. The three questions that matter most are net new assets, market levels, adviser custody, retention, and organic growth, sweep balances, money funds, deposits, supplemental funding, and deposit beta, securities duration, unrealized losses, capital, liquidity, and net interest margin.","sells":"Brokerage, custody, advice, deposits, lending, money funds, ETFs, mutual funds, trading, and retirement services.","revenueModel":"Net interest revenue, asset-management and administration fees, trading revenue, advice fees, and bank-related income.","opportunity":"Cash realignment normalization, net new assets, adviser growth, and balance-sheet repositioning can lift earnings.","mustGoRight":"Funding costs must normalize, securities losses must remain manageable, client service must improve, and organic asset gathering must persist.","editorNote":"Treat the claimed advantage—scale, low-cost distribution, adviser custody, brand, and client assets can support durable gathering and operating leverage.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Scale, low-cost distribution, adviser custody, brand, and client assets can support durable gathering and operating leverage.","Cash realignment normalization, net new assets, adviser growth, and balance-sheet repositioning can lift earnings.","Visible progress in client assets and client cash can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Liquidity and duration can weaken the owner outcome; monitor deposit outflows, borrowing, securities marks, capital, and hedging.","Service and integration can weaken the owner outcome; monitor call times, platform conversion, adviser satisfaction, and attrition.","Market and fee sensitivity can weaken the owner outcome; monitor asset levels, money-market fees, trading, and rate changes.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if client cash sorting and funding pressure remain structural while service shortcomings weaken asset gathering.","financialDrivers":[{"label":"CLIENT ASSETS","value":"Primary owner KPI","detail":"net new assets, market levels, adviser custody, retention, and organic growth"},{"label":"CLIENT CASH","value":"Primary owner KPI","detail":"sweep balances, money funds, deposits, supplemental funding, and deposit beta"},{"label":"BALANCE SHEET","value":"Primary owner KPI","detail":"securities duration, unrealized losses, capital, liquidity, and net interest margin"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Liquidity and duration","level":"High","text":"Liquidity and duration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"deposit outflows, borrowing, securities marks, capital, and hedging"},{"title":"Service and integration","level":"High","text":"Service and integration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"call times, platform conversion, adviser satisfaction, and attrition"},{"title":"Market and fee sensitivity","level":"High","text":"Market and fee sensitivity can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"asset levels, money-market fees, trading, and rate changes"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"CLIENT ASSETS","text":"Track net new assets, market levels, adviser custody, retention, and organic growth and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"CLIENT CASH","text":"Track sweep balances, money funds, deposits, supplemental funding, and deposit beta and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"BALANCE SHEET","text":"Track securities duration, unrealized losses, capital, liquidity, and net interest margin and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies client assets?","What would cause client cash to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in balance sheet?","Where does CHARLES SCHWAB Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Interactive Brokers Group, Inc., MORGAN STANLEY, JPMORGAN CHASE & CO, Robinhood Markets, Inc., LPL Financial Holdings Inc., RAYMOND JAMES FINANCIAL INC","comparables":[{"name":"Interactive Brokers Group, Inc.","ticker":"IBKR","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001381197&owner=exclude"},{"name":"MORGAN STANLEY","ticker":"MS","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000895421&owner=exclude"},{"name":"JPMORGAN CHASE & CO","ticker":"JPM","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000019617&owner=exclude"},{"name":"Robinhood Markets, Inc.","ticker":"HOOD","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001783879&owner=exclude"},{"name":"LPL Financial Holdings Inc.","ticker":"LPLA","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001397911&owner=exclude"},{"name":"RAYMOND JAMES FINANCIAL INC","ticker":"RJF","ownership":"Public","relationship":"Operating and valuation reference for SCHW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SCHW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000720005&owner=exclude"}],"sources":[{"title":"SCHW SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000316709&owner=exclude","excerpt":"SCHWAB CHARLES CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"SCHW annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000316709&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"SCHW quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000316709&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"SCHW proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000316709&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"SCHW investor relations","meta":"Company primary materials","href":"https://www.aboutschwab.com/investor-relations","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"SCHW official newsroom","meta":"Company announcements","href":"https://pressroom.aboutschwab.com/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
