INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('BLK', 'published', '{"ticker":"BLK","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.blackrock.com/corporate/newsroom","description":"Global asset manager and technology provider offering index, active, alternatives, cash, advisory, and Aladdin services.","lede":"BLACKROCK Inc. earns owner value through fees based on assets under management, performance fees, technology subscriptions, advisory fees, and securities lending. The three questions that matter most are ishares, active, cash, institutional, retail, and long-term net inflows, aum levels, mix, fee rates, performance, and securities lending, fundraising, deployment, realizations, aladdin contracts, and acquisition integration.","sells":"ETFs, mutual funds, institutional mandates, private markets, cash management, advisory, and investment technology.","revenueModel":"Fees based on assets under management, performance fees, technology subscriptions, advisory fees, and securities lending.","opportunity":"ETF adoption, private markets, retirement, outsourced solutions, and technology can expand fees and strategic relevance.","mustGoRight":"Organic flows must remain strong, acquisitions must integrate, private-market returns must support fundraising, and fee compression must be contained.","editorNote":"Treat the claimed advantage—global distribution, ishares scale, aladdin data and workflows, and institutional relationships can reinforce asset gathering.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Global distribution, iShares scale, Aladdin data and workflows, and institutional relationships can reinforce asset gathering.","ETF adoption, private markets, retirement, outsourced solutions, and technology can expand fees and strategic relevance.","Visible progress in organic flows and base fees can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Markets and fee compression can weaken the owner outcome; monitor aum, mix, pricing, passive competition, and waivers.","Acquisition execution can weaken the owner outcome; monitor gip, hps, preqin, leverage, retention, synergies, and returns.","Political and fiduciary risk can weaken the owner outcome; monitor mandate losses, voting policy, regulation, and litigation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if organic growth and technology monetization fail to offset fee pressure and large acquisitions dilute returns.","financialDrivers":[{"label":"ORGANIC FLOWS","value":"Primary owner KPI","detail":"iShares, active, cash, institutional, retail, and long-term net inflows"},{"label":"BASE FEES","value":"Primary owner KPI","detail":"AUM levels, mix, fee rates, performance, and securities lending"},{"label":"PRIVATE MARKETS & TECHNOLOGY","value":"Primary owner KPI","detail":"fundraising, deployment, realizations, Aladdin contracts, and acquisition integration"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Markets and fee compression","level":"High","text":"Markets and fee compression can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"AUM, mix, pricing, passive competition, and waivers"},{"title":"Acquisition execution","level":"High","text":"Acquisition execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"GIP, HPS, Preqin, leverage, retention, synergies, and returns"},{"title":"Political and fiduciary risk","level":"High","text":"Political and fiduciary risk can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"mandate losses, voting policy, regulation, and litigation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"ORGANIC FLOWS","text":"Track ishares, active, cash, institutional, retail, and long-term net inflows and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"BASE FEES","text":"Track aum levels, mix, fee rates, performance, and securities lending and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"PRIVATE MARKETS & TECHNOLOGY","text":"Track fundraising, deployment, realizations, aladdin contracts, and acquisition integration and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies organic flows?","What would cause base fees to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in private markets & technology?","Where does BLACKROCK Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"PRICE T ROWE GROUP INC, FRANKLIN RESOURCES INC, Invesco Ltd., Blackstone Inc., KKR & Co. Inc., MORGAN STANLEY","comparables":[{"name":"PRICE T ROWE GROUP INC","ticker":"TROW","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001113169&owner=exclude"},{"name":"FRANKLIN RESOURCES INC","ticker":"BEN","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000038777&owner=exclude"},{"name":"Invesco Ltd.","ticker":"IVZ","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000914208&owner=exclude"},{"name":"Blackstone Inc.","ticker":"BX","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001393818&owner=exclude"},{"name":"KKR & Co. Inc.","ticker":"KKR","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001404912&owner=exclude"},{"name":"MORGAN STANLEY","ticker":"MS","ownership":"Public","relationship":"Operating and valuation reference for BLK","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with BLK.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000895421&owner=exclude"}],"sources":[{"title":"BLK SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0002012383&owner=exclude","excerpt":"BlackRock, Inc. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"BLK annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0002012383&type=10-K&owner=exclude&count=40","excerpt":"Annual reports