INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('DE', 'published', '{"ticker":"DE","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.deere.com/en/news/","description":"Agricultural, construction, and forestry equipment company with precision technology and captive finance operations.","lede":"DEERE earns owner value through equipment and parts sales, subscriptions and technology, dealer channels, and financing income. The three questions that matter most are farmer income, crop prices, fleet age, units, price, mix, and dealer inventory, enabled acres, subscriptions, utilization, customer savings, and attachment, housing and infrastructure demand, receivables, delinquencies, and residual values.","sells":"Tractors, combines, sprayers, construction and forestry equipment, engines, parts, precision-ag software, and financing.","revenueModel":"Equipment and parts sales, subscriptions and technology, dealer channels, and financing income.","opportunity":"Autonomy, precision agriculture, fleet renewal, parts, and emerging-market productivity can deepen customer value.","mustGoRight":"Dealer inventory must normalize, precision tools must earn measurable farm returns, and finance losses must remain controlled.","editorNote":"Treat the claimed advantage—brand, dealer support, installed equipment, agronomic data, and integrated precision technology can support lifecycle economics.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Brand, dealer support, installed equipment, agronomic data, and integrated precision technology can support lifecycle economics.","Autonomy, precision agriculture, fleet renewal, parts, and emerging-market productivity can deepen customer value.","Visible progress in ag equipment and precision & autonomy can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Agricultural cycle can weaken the owner outcome; monitor crop prices, farm income, interest, used equipment, and dealer inventory.","Technology adoption can weaken the owner outcome; monitor customer roi, reliability, subscriptions, data, and competitive offerings.","Finance and production can weaken the owner outcome; monitor credit losses, residuals, suppliers, labor, inventory, and warranty.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if technology investment fails to improve customer economics and equipment share while the cycle and finance losses weaken returns.","financialDrivers":[{"label":"AG EQUIPMENT","value":"Primary owner KPI","detail":"farmer income, crop prices, fleet age, units, price, mix, and dealer inventory"},{"label":"PRECISION & AUTONOMY","value":"Primary owner KPI","detail":"enabled acres, subscriptions, utilization, customer savings, and attachment"},{"label":"CONSTRUCTION & FINANCE","value":"Primary owner KPI","detail":"housing and infrastructure demand, receivables, delinquencies, and residual values"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Agricultural cycle","level":"High","text":"Agricultural cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"crop prices, farm income, interest, used equipment, and dealer inventory"},{"title":"Technology adoption","level":"High","text":"Technology adoption can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"customer ROI, reliability, subscriptions, data, and competitive offerings"},{"title":"Finance and production","level":"High","text":"Finance and production can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"credit losses, residuals, suppliers, labor, inventory, and warranty"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"AG EQUIPMENT","text":"Track farmer income, crop prices, fleet age, units, price, mix, and dealer inventory and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"PRECISION & AUTONOMY","text":"Track enabled acres, subscriptions, utilization, customer savings, and attachment and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CONSTRUCTION & FINANCE","text":"Track housing and infrastructure demand, receivables, delinquencies, and residual values and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies ag equipment?","What would cause precision & autonomy to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in construction & finance?","Where does DEERE have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"CATERPILLAR INC, AGCO CORP /DE, CNH Industrial N.V., PACCAR INC, TEREX CORP, UNITED RENTALS, INC.","comparables":[{"name":"CATERPILLAR INC","ticker":"CAT","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000018230&owner=exclude"},{"name":"AGCO CORP /DE","ticker":"AGCO","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000880266&owner=exclude"},{"name":"CNH Industrial N.V.","ticker":"CNH","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001567094&owner=exclude"},{"name":"PACCAR INC","ticker":"PCAR","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000075362&owner=exclude"},{"name":"TEREX CORP","ticker":"TEX","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000097216&owner=exclude"},{"name":"UNITED RENTALS, INC.","ticker":"URI","ownership":"Public","relationship":"Operating and valuation reference for DE","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DE.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001067701&owner=exclude"}],"sources":[{"title":"DE SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000315189&owner=exclude","excerpt":"DEERE & CO filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"DE annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000315189&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"DE quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000315189&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"DE proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000315189&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"DE investor relations","meta":"Company primary materials","href":"https://www.deere.com/en/our-company/investor-relations/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"DE official newsroom","meta":"Company announcements","href":"https://www.deere.com/en/news/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
