INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('MRVL', 'published', '{"ticker":"MRVL","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.marvell.com/company/newsroom.html","description":"Fabless semiconductor company focused on data infrastructure, custom compute, networking, storage, and carrier connectivity.","lede":"MARVELL TECHNOLOGY Inc. earns owner value through semiconductor product sales and custom-program economics through cloud, oem, networking, storage, and carrier customers. The three questions that matter most are custom accelerators, optics, interconnect, switching, program ramps, and customer concentration, tape-outs, qualification, production timing, lifetime value, and gross margin, carrier, enterprise, storage, inventory, pricing, and recovery.","sells":"Custom accelerators, interconnect, switching, optical DSPs, storage controllers, processors, and carrier silicon.","revenueModel":"Semiconductor product sales and custom-program economics through cloud, OEM, networking, storage, and carrier customers.","opportunity":"AI custom compute, electro-optics, switching, and interconnect can drive multiyear program growth.","mustGoRight":"Design wins must reach production, customer concentration must be managed, and core carrier and storage markets must stabilize.","editorNote":"Treat the claimed advantage—high-speed connectivity, custom silicon, and data-infrastructure expertise can capture content as cloud architectures scale.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["High-speed connectivity, custom silicon, and data-infrastructure expertise can capture content as cloud architectures scale.","AI custom compute, electro-optics, switching, and interconnect can drive multiyear program growth.","Visible progress in ai revenue and design-win conversion can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Customer and program concentration can weaken the owner outcome; monitor top customers, milestones, cancellations, pricing, and insourcing.","Technology and foundry execution can weaken the owner outcome; monitor tape-outs, yields, nodes, packaging, supply, and roadmap.","Margin and cash conversion can weaken the owner outcome; monitor mix, nre, inventory, stock compensation, and free cash flow.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if announced AI programs fail to convert or margins and cash remain inadequate after substantial custom-silicon investment.","financialDrivers":[{"label":"AI REVENUE","value":"Primary owner KPI","detail":"custom accelerators, optics, interconnect, switching, program ramps, and customer concentration"},{"label":"DESIGN-WIN CONVERSION","value":"Primary owner KPI","detail":"tape-outs, qualification, production timing, lifetime value, and gross margin"},{"label":"CORE MARKETS","value":"Primary owner KPI","detail":"carrier, enterprise, storage, inventory, pricing, and recovery"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Customer and program concentration","level":"High","text":"Customer and program concentration can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"top customers, milestones, cancellations, pricing, and insourcing"},{"title":"Technology and foundry execution","level":"High","text":"Technology and foundry execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"tape-outs, yields, nodes, packaging, supply, and roadmap"},{"title":"Margin and cash conversion","level":"High","text":"Margin and cash conversion can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"mix, NRE, inventory, stock compensation, and free cash flow"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"AI REVENUE","text":"Track custom accelerators, optics, interconnect, switching, program ramps, and customer concentration and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"DESIGN-WIN CONVERSION","text":"Track tape-outs, qualification, production timing, lifetime value, and gross margin and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CORE MARKETS","text":"Track carrier, enterprise, storage, inventory, pricing, and recovery and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies ai revenue?","What would cause design-win conversion to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in core markets?","Where does MARVELL TECHNOLOGY Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Broadcom Inc., NVIDIA CORP, ADVANCED MICRO DEVICES INC, Arista Networks, Inc., MICROCHIP TECHNOLOGY INC, QUALCOMM INC/DE","comparables":[{"name":"Broadcom Inc.","ticker":"AVGO","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001730168&owner=exclude"},{"name":"NVIDIA CORP","ticker":"NVDA","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001045810&owner=exclude"},{"name":"ADVANCED MICRO DEVICES INC","ticker":"AMD","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000002488&owner=exclude"},{"name":"Arista Networks, Inc.","ticker":"ANET","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001596532&owner=exclude"},{"name":"MICROCHIP TECHNOLOGY INC","ticker":"MCHP","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000827054&owner=exclude"},{"name":"QUALCOMM INC/DE","ticker":"QCOM","ownership":"Public","relationship":"Operating and valuation reference for MRVL","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MRVL.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000804328&owner=exclude"}],"sources":[{"title":"MRVL SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001835632&owner=exclude","excerpt":"Marvell Technology, Inc. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"MRVL annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001835632&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"MRVL quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001835632&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"MRVL proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001835632&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"MRVL investor relations","meta":"Company primary materials","href":"https://investor.marvell.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"MRVL official newsroom","meta":"Company announcements","href":"https://www.marvell.com/company/newsroom.html","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
