INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('T', 'published', '{"ticker":"T","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://about.att.com/pages/corporate_news","description":"U.S. communications company focused on wireless service and fiber broadband.","lede":"AT&T Inc. earns owner value through recurring wireless and broadband subscriptions, equipment sales, wholesale, and business service revenue. The three questions that matter most are postpaid phones, churn, arpu, promotions, and service margin, locations passed, penetration, net adds, arpu, build cost, and convergence, ebitda, capex, device working capital, interest, debt reduction, and dividends.","sells":"Consumer and business wireless, devices, fiber broadband, wholesale access, and enterprise connectivity.","revenueModel":"Recurring wireless and broadband subscriptions, equipment sales, wholesale, and business service revenue.","opportunity":"Fiber penetration, converged households, wireless ARPU, and cost discipline can improve growth and free cash flow.","mustGoRight":"Fiber returns must justify capital, wireless churn and pricing must remain sound, and debt and legacy liabilities must decline.","editorNote":"Treat the claimed advantage—nationwide wireless scale, expanding fiber, distribution, and converged offers can support durable connectivity cash flow.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Nationwide wireless scale, expanding fiber, distribution, and converged offers can support durable connectivity cash flow.","Fiber penetration, converged households, wireless ARPU, and cost discipline can improve growth and free cash flow.","Visible progress in wireless service and fiber can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Competition and promotions can weaken the owner outcome; monitor churn, gross adds, pricing, handset subsidies, and market share.","Capital intensity can weaken the owner outcome; monitor fiber build, network capex, spectrum, returns, and maintenance.","Debt and legacy liabilities can weaken the owner outcome; monitor interest, maturities, lead-sheathed cable claims, pension, and litigation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if network investment fails to produce subscriber and cash growth while leverage and legacy liabilities remain elevated.","financialDrivers":[{"label":"WIRELESS SERVICE","value":"Primary owner KPI","detail":"postpaid phones, churn, ARPU, promotions, and service margin"},{"label":"FIBER","value":"Primary owner KPI","detail":"locations passed, penetration, net adds, ARPU, build cost, and convergence"},{"label":"FREE CASH FLOW","value":"Primary owner KPI","detail":"EBITDA, capex, device working capital, interest, debt reduction, and dividends"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Competition and promotions","level":"High","text":"Competition and promotions can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"churn, gross adds, pricing, handset subsidies, and market share"},{"title":"Capital intensity","level":"High","text":"Capital intensity can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"fiber build, network capex, spectrum, returns, and maintenance"},{"title":"Debt and legacy liabilities","level":"High","text":"Debt and legacy liabilities can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"interest, maturities, lead-sheathed cable claims, pension, and litigation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"WIRELESS SERVICE","text":"Track postpaid phones, churn, arpu, promotions, and service margin and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"FIBER","text":"Track locations passed, penetration, net adds, arpu, build cost, and convergence and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"FREE CASH FLOW","text":"Track ebitda, capex, device working capital, interest, debt reduction, and dividends and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies wireless service?","What would cause fiber to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in free cash flow?","Where does AT&T Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"VERIZON COMMUNICATIONS INC, T-Mobile US, Inc., CHARTER COMMUNICATIONS, INC., COMCAST CORP, Lumen Technologies, Inc., DTEGY","comparables":[{"name":"VERIZON COMMUNICATIONS INC","ticker":"VZ","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000732712&owner=exclude"},{"name":"T-Mobile US, Inc.","ticker":"TMUS","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001283699&owner=exclude"},{"name":"CHARTER COMMUNICATIONS, INC.","ticker":"CHTR","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001091667&owner=exclude"},{"name":"COMCAST CORP","ticker":"CMCSA","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001166691&owner=exclude"},{"name":"Lumen Technologies, Inc.","ticker":"LUMN","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000018926&owner=exclude"},{"name":"DTEGY","ticker":"DTEGY","ownership":"Public","relationship":"Operating and valuation reference for T","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with T.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=DTEGY&owner=exclude"}],"sources":[{"title":"T SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000732717&owner=exclude","excerpt":"AT&T INC. filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"T annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732717&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"T quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732717&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"T proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000732717&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"T investor relations","meta":"Company primary materials","href":"https://investors.att.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"T official newsroom","meta":"Company announcements","href":"https://about.att.com/pages/corporate_news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
