INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('UBER', 'published', '{"ticker":"UBER","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.uber.com/newsroom/","description":"Mobility, delivery, and freight marketplace connecting consumers, drivers, couriers, merchants, and shippers.","lede":"UBER TECHNOLOGIES Inc. earns owner value through marketplace take rates, service fees, advertising, subscriptions, logistics margin, and other platform revenue. The three questions that matter most are trips, frequency, audience, price, mobility, delivery, and geography, pricing, driver pay, promotions, insurance, mix, and contribution margin, adjusted earnings, stock compensation, insurance reserves, working capital, and capital allocation.","sells":"Ride-hailing, delivery, grocery, advertising, memberships, freight brokerage, and emerging autonomous-vehicle distribution.","revenueModel":"Marketplace take rates, service fees, advertising, subscriptions, logistics margin, and other platform revenue.","opportunity":"Mobility penetration, delivery advertising, memberships, enterprise use, and autonomous partnerships can expand cash flow.","mustGoRight":"Bookings must grow without uneconomic incentives, regulation must preserve contractor economics, and autonomous vehicles must complement the platform.","editorNote":"Treat the claimed advantage—marketplace liquidity, global demand, local supply, routing, payments, and cross-product membership can reinforce frequency.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Marketplace liquidity, global demand, local supply, routing, payments, and cross-product membership can reinforce frequency.","Mobility penetration, delivery advertising, memberships, enterprise use, and autonomous partnerships can expand cash flow.","Visible progress in gross bookings and take rate & incentives can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Driver classification and regulation can weaken the owner outcome; monitor laws, minimum pay, benefits, taxes, licenses, and litigation.","Competition and incentives can weaken the owner outcome; monitor driver supply, wait times, promotions, take rate, and share.","Autonomous disruption can weaken the owner outcome; monitor partnership economics, fleet ownership, routing share, safety, and disintermediation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if regulation and competition structurally compress take rates and autonomy disintermediates rather than strengthens the network.","financialDrivers":[{"label":"GROSS BOOKINGS","value":"Primary owner KPI","detail":"trips, frequency, audience, price, mobility, delivery, and geography"},{"label":"TAKE RATE & INCENTIVES","value":"Primary owner KPI","detail":"pricing, driver pay, promotions, insurance, mix, and contribution margin"},{"label":"FREE CASH FLOW","value":"Primary owner KPI","detail":"adjusted earnings, stock compensation, insurance reserves, working capital, and capital allocation"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Driver classification and regulation","level":"High","text":"Driver classification and regulation can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"laws, minimum pay, benefits, taxes, licenses, and litigation"},{"title":"Competition and incentives","level":"High","text":"Competition and incentives can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"driver supply, wait times, promotions, take rate, and share"},{"title":"Autonomous disruption","level":"High","text":"Autonomous disruption can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"partnership economics, fleet ownership, routing share, safety, and disintermediation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"GROSS BOOKINGS","text":"Track trips, frequency, audience, price, mobility, delivery, and geography and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"TAKE RATE & INCENTIVES","text":"Track pricing, driver pay, promotions, insurance, mix, and contribution margin and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"FREE CASH FLOW","text":"Track adjusted earnings, stock compensation, insurance reserves, working capital, and capital allocation and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies gross bookings?","What would cause take rate & incentives to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in free cash flow?","Where does UBER TECHNOLOGIES Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"Lyft, Inc., DoorDash, Inc., Airbnb, Inc., Booking Holdings Inc., AMAZON COM INC, FEDEX CORP","comparables":[{"name":"Lyft, Inc.","ticker":"LYFT","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001759509&owner=exclude"},{"name":"DoorDash, Inc.","ticker":"DASH","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001792789&owner=exclude"},{"name":"Airbnb, Inc.","ticker":"ABNB","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001559720&owner=exclude"},{"name":"Booking Holdings Inc.","ticker":"BKNG","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001075531&owner=exclude"},{"name":"AMAZON COM INC","ticker":"AMZN","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001018724&owner=exclude"},{"name":"FEDEX CORP","ticker":"FDX","ownership":"Public","relationship":"Operating and valuation reference for UBER","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with UBER.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001048911&owner=exclude"}],"sources":[{"title":"UBER SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001543151&owner=exclude","excerpt":"Uber Technologies, Inc filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"UBER annual reports","meta":"SEC Forms 10-K · Primary 