INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('DHR', 'published', '{"ticker":"DHR","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.danaher.com/news","description":"Life-sciences and diagnostics company operating through biotechnology, life sciences, and diagnostics platforms.","lede":"DANAHER Corp. earns owner value through instrument sales, recurring consumables, reagents, service, software, and workflow solutions. The three questions that matter most are orders, consumables, destocking, utilization, funding, and customer production, test volume, installed base, menu, pricing, and health-system demand, volume, price, productivity, mix, r&d, and free cash flow.","sells":"Bioprocessing tools and consumables, microscopy and analytical instruments, clinical diagnostics, and related services.","revenueModel":"Instrument sales, recurring consumables, reagents, service, software, and workflow solutions.","opportunity":"Bioprocess recovery, biologics, precision diagnostics, and productivity can restore organic growth and margin.","mustGoRight":"Bioprocess inventory must normalize, acquisitions must earn returns, and operating discipline must preserve innovation.","editorNote":"Treat the claimed advantage—danaher business system, recurring consumables, installed bases, and disciplined portfolio management can support returns.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Danaher Business System, recurring consumables, installed bases, and disciplined portfolio management can support returns.","Bioprocess recovery, biologics, precision diagnostics, and productivity can restore organic growth and margin.","Visible progress in bioprocessing and diagnostics can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Biopharma cycle can weaken the owner outcome; monitor funding, inventory, utilization, capacity, and order trends.","Acquisition and portfolio execution can weaken the owner outcome; monitor purchase price, integration, organic growth, goodwill, and returns.","China and regulation can weaken the owner outcome; monitor procurement, localization, trade policy, diagnostics rules, and pricing.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if recurring growth remains structurally weak and portfolio acquisitions fail to produce adequate organic growth and cash returns.","financialDrivers":[{"label":"BIOPROCESSING","value":"Primary owner KPI","detail":"orders, consumables, destocking, utilization, funding, and customer production"},{"label":"DIAGNOSTICS","value":"Primary owner KPI","detail":"test volume, installed base, menu, pricing, and health-system demand"},{"label":"CORE GROWTH & MARGIN","value":"Primary owner KPI","detail":"volume, price, productivity, mix, R&D, and free cash flow"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Biopharma cycle","level":"High","text":"Biopharma cycle can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"funding, inventory, utilization, capacity, and order trends"},{"title":"Acquisition and portfolio execution","level":"High","text":"Acquisition and portfolio execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"purchase price, integration, organic growth, goodwill, and returns"},{"title":"China and regulation","level":"High","text":"China and regulation can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"procurement, localization, trade policy, diagnostics rules, and pricing"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"BIOPROCESSING","text":"Track orders, consumables, destocking, utilization, funding, and customer production and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"DIAGNOSTICS","text":"Track test volume, installed base, menu, pricing, and health-system demand and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CORE GROWTH & MARGIN","text":"Track volume, price, productivity, mix, r&d, and free cash flow and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies bioprocessing?","What would cause diagnostics to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in core growth & margin?","Where does DANAHER Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"THERMO FISHER SCIENTIFIC INC., AGILENT TECHNOLOGIES, INC., WATERS CORP, REVVITY, INC., BECTON DICKINSON & CO, IQVIA HOLDINGS INC.","comparables":[{"name":"THERMO FISHER SCIENTIFIC INC.","ticker":"TMO","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000097745&owner=exclude"},{"name":"AGILENT TECHNOLOGIES, INC.","ticker":"A","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001090872&owner=exclude"},{"name":"WATERS CORP","ticker":"WAT","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001000697&owner=exclude"},{"name":"REVVITY, INC.","ticker":"RVTY","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000031791&owner=exclude"},{"name":"BECTON DICKINSON & CO","ticker":"BDX","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000010795&owner=exclude"},{"name":"IQVIA HOLDINGS INC.","ticker":"IQV","ownership":"Public","relationship":"Operating and valuation reference for DHR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with DHR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001478242&owner=exclude"}],"sources":[{"title":"DHR SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000313616&owner=exclude","excerpt":"DANAHER CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"DHR annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000313616&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"DHR quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000313616&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"DHR proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000313616&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"DHR investor relations","meta":"Company primary materials","href":"https://investors.danaher.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"DHR official newsroom","meta":"Company announcements","href":"https://www.danaher.com/news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
