INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('LMT', 'published', '{"ticker":"LMT","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://news.lockheedmartin.com/","description":"Global defense contractor focused on aeronautics, missiles, rotary and mission systems, and space.","lede":"LOCKHEED MARTIN Corp. earns owner value through cost-plus and fixed-price government contracts, production lots, development programs, sustainment, and international military sales. The three questions that matter most are deliveries, upgrades, sustainment, payment timing, supplier cost, and international demand, orders, production capacity, milestones, fixed-price exposure, and margin, advances, working capital, pension, capex, program charges, and capital returns.","sells":"Fighter aircraft, missiles, missile defense, helicopters, radars, naval systems, satellites, strategic systems, and sustainment.","revenueModel":"Cost-plus and fixed-price government contracts, production lots, development programs, sustainment, and international military sales.","opportunity":"Defense modernization, allied demand, munitions replenishment, F-35 sustainment, missile defense, and space can grow cash flow.","mustGoRight":"Fixed-price development must remain controlled, suppliers must support production, and customer funding and approvals must convert backlog.","editorNote":"Treat the claimed advantage—classified capabilities, installed platforms, technical depth, and long program lives can support backlog and sustainment.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Classified capabilities, installed platforms, technical depth, and long program lives can support backlog and sustainment.","Defense modernization, allied demand, munitions replenishment, F-35 sustainment, missile defense, and space can grow cash flow.","Visible progress in f-35 and missiles & space can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Program execution can weaken the owner outcome; monitor cost estimates, schedule, technical milestones, charges, and customer acceptance.","Budget and geopolitical exposure can weaken the owner outcome; monitor appropriations, continuing resolutions, export approvals, and policy.","Supply and production can weaken the owner outcome; monitor solid rocket motors, electronics, labor, quality, and lead times.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if repeated program charges and supplier constraints prevent backlog from converting into adequate cash returns.","financialDrivers":[{"label":"F-35","value":"Primary owner KPI","detail":"deliveries, upgrades, sustainment, payment timing, supplier cost, and international demand"},{"label":"MISSILES & SPACE","value":"Primary owner KPI","detail":"orders, production capacity, milestones, fixed-price exposure, and margin"},{"label":"CASH CONVERSION","value":"Primary owner KPI","detail":"advances, working capital, pension, capex, program charges, and capital returns"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Program execution","level":"High","text":"Program execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"cost estimates, schedule, technical milestones, charges, and customer acceptance"},{"title":"Budget and geopolitical exposure","level":"High","text":"Budget and geopolitical exposure can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"appropriations, continuing resolutions, export approvals, and policy"},{"title":"Supply and production","level":"High","text":"Supply and production can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"solid rocket motors, electronics, labor, quality, and lead times"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"F-35","text":"Track deliveries, upgrades, sustainment, payment timing, supplier cost, and international demand and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"MISSILES & SPACE","text":"Track orders, production capacity, milestones, fixed-price exposure, and margin and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CASH CONVERSION","text":"Track advances, working capital, pension, capex, program charges, and capital returns and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies f-35?","What would cause missiles & space to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in cash conversion?","Where does LOCKHEED MARTIN Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"RTX Corp, NORTHROP GRUMMAN CORP, GENERAL DYNAMICS CORP, BOEING CO, L3HARRIS TECHNOLOGIES, INC., HUNTINGTON INGALLS INDUSTRIES, INC.","comparables":[{"name":"RTX Corp","ticker":"RTX","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000101829&owner=exclude"},{"name":"NORTHROP GRUMMAN CORP","ticker":"NOC","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001133421&owner=exclude"},{"name":"GENERAL DYNAMICS CORP","ticker":"GD","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000040533&owner=exclude"},{"name":"BOEING CO","ticker":"BA","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000012927&owner=exclude"},{"name":"L3HARRIS TECHNOLOGIES, INC.","ticker":"LHX","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000202058&owner=exclude"},{"name":"HUNTINGTON INGALLS INDUSTRIES, INC.","ticker":"HII","ownership":"Public","relationship":"Operating and valuation reference for LMT","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with LMT.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001501585&owner=exclude"}],"sources":[{"title":"LMT SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000936468&owner=exclude","excerpt":"LOCKHEED MARTIN CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"LMT annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000936468&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"LMT quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000936468&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"LMT proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000936468&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"LMT investor relations","meta":"Company primary materials","href":"https://www.lockheedmartin.com/en-us/investor-relations.html","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"LMT official newsroom","meta":"Company announcements","href":"https://news.lockheedmartin.com/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
