INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('PGR', 'published', '{"ticker":"PGR","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.progressive.com/newsroom/","description":"U.S. insurer focused on personal and commercial auto, property, and related products.","lede":"PROGRESSIVE Corp. earns owner value through insurance premiums and investment income net of claims, loss adjustment, commissions, and operating expenses. The three questions that matter most are quotes, conversion, retention, rate, channels, and customer segments, frequency, severity, repair cost, catastrophe, pricing, and expenses, development, reinsurance, investment portfolio, surplus, and dividends.","sells":"Personal auto, commercial auto, homeowners, renters, motorcycle, boat, and other insurance.","revenueModel":"Insurance premiums and investment income net of claims, loss adjustment, commissions, and operating expenses.","opportunity":"Policy growth, better segmentation, bundled households, and disciplined pricing can compound premiums and book value.","mustGoRight":"Pricing must stay ahead of severity, reserves must remain sound, and growth must not sacrifice target margins.","editorNote":"Treat the claimed advantage—segmentation, telematics, direct distribution, agent relationships, and rapid pricing can support underwriting advantage.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Segmentation, telematics, direct distribution, agent relationships, and rapid pricing can support underwriting advantage.","Policy growth, better segmentation, bundled households, and disciplined pricing can compound premiums and book value.","Visible progress in policy growth and combined ratio can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Loss-cost inflation can weaken the owner outcome; monitor repair parts, labor, medical, litigation, weather, and driving patterns.","Reserve adequacy can weaken the owner outcome; monitor prior-year development, claim closure, severity, and reinsurance.","Pricing and regulation can weaken the owner outcome; monitor rate approvals, customer shopping, competitor actions, and retention.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if loss-cost segmentation and reserve estimates repeatedly lag severity, eliminating the underwriting advantage.","financialDrivers":[{"label":"POLICY GROWTH","value":"Primary owner KPI","detail":"quotes, conversion, retention, rate, channels, and customer segments"},{"label":"COMBINED RATIO","value":"Primary owner KPI","detail":"frequency, severity, repair cost, catastrophe, pricing, and expenses"},{"label":"RESERVES & CAPITAL","value":"Primary owner KPI","detail":"development, reinsurance, investment portfolio, surplus, and dividends"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Loss-cost inflation","level":"High","text":"Loss-cost inflation can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"repair parts, labor, medical, litigation, weather, and driving patterns"},{"title":"Reserve adequacy","level":"High","text":"Reserve adequacy can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"prior-year development, claim closure, severity, and reinsurance"},{"title":"Pricing and regulation","level":"High","text":"Pricing and regulation can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"rate approvals, customer shopping, competitor actions, and retention"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"POLICY GROWTH","text":"Track quotes, conversion, retention, rate, channels, and customer segments and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"COMBINED RATIO","text":"Track frequency, severity, repair cost, catastrophe, pricing, and expenses and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"RESERVES & CAPITAL","text":"Track development, reinsurance, investment portfolio, surplus, and dividends and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies policy growth?","What would cause combined ratio to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in reserves & capital?","Where does PROGRESSIVE Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"ALLSTATE CORP, TRAVELERS COMPANIES, INC., Chubb Ltd, ARCH CAPITAL GROUP LTD., AMERICAN INTERNATIONAL GROUP, INC., HARTFORD INSURANCE GROUP, INC.","comparables":[{"name":"ALLSTATE CORP","ticker":"ALL","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000899051&owner=exclude"},{"name":"TRAVELERS COMPANIES, INC.","ticker":"TRV","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000086312&owner=exclude"},{"name":"Chubb Ltd","ticker":"CB","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000896159&owner=exclude"},{"name":"ARCH CAPITAL GROUP LTD.","ticker":"ACGL","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000947484&owner=exclude"},{"name":"AMERICAN INTERNATIONAL GROUP, INC.","ticker":"AIG","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000005272&owner=exclude"},{"name":"HARTFORD INSURANCE GROUP, INC.","ticker":"HIG","ownership":"Public","relationship":"Operating and valuation reference for PGR","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PGR.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000874766&owner=exclude"}],"sources":[{"title":"PGR SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000080661&owner=exclude","excerpt":"PROGRESSIVE CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"PGR annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000080661&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"PGR quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000080661&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"PGR proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000080661&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"PGR investor relations","meta":"Company primary materials","href":"https://investors.progressive.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"PGR official newsroom","meta":"Company announcements","href":"https://www.progressive.com/newsroom/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
