INSERT INTO company_dossiers (ticker, status, content_json, verified_by, verified_at, published_at, updated_at)
VALUES ('SBUX', 'published', '{"ticker":"SBUX","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://about.starbucks.com/press/","description":"Global coffee retailer and consumer-products brand operating company-owned and licensed stores.","lede":"STARBUCKS Corp. earns owner value through company-operated store sales, licensed-store royalties and product sales, consumer packaged goods, and partnership income. The three questions that matter most are traffic, frequency, ticket, promotions, loyalty, speed, and customer satisfaction, labor hours, throughput, equipment, waste, occupancy, and four-wall margin, transactions, store growth, pricing, competition, licensing, and returns.","sells":"Coffee, tea, cold beverages, food, packaged coffee, ready-to-drink products, loyalty, delivery, and licensed stores.","revenueModel":"Company-operated store sales, licensed-store royalties and product sales, consumer packaged goods, and partnership income.","opportunity":"Store throughput, menu simplification, loyalty, international growth, and partner engagement can restore traffic and margins.","mustGoRight":"U.S. traffic and speed must recover, China economics must stabilize, labor relations must improve, and store investment must earn returns.","editorNote":"Treat the claimed advantage—brand, store network, loyalty, premium beverages, and habitual customer relationships can support frequency and pricing.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Brand, store network, loyalty, premium beverages, and habitual customer relationships can support frequency and pricing.","Store throughput, menu simplification, loyalty, international growth, and partner engagement can restore traffic and margins.","Visible progress in u.s. transactions and store economics can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Brand and traffic can weaken the owner outcome; monitor transactions, value scores, wait times, menu relevance, and competitor share.","Labor and execution can weaken the owner outcome; monitor wages, scheduling, union activity, turnover, service, and store complexity.","China competition can weaken the owner outcome; monitor price promotion, local brands, store productivity, delivery, and consumer demand.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if traffic and customer relevance fail to recover despite sustained labor, equipment, promotion, and store investment.","financialDrivers":[{"label":"U.S. TRANSACTIONS","value":"Primary owner KPI","detail":"traffic, frequency, ticket, promotions, loyalty, speed, and customer satisfaction"},{"label":"STORE ECONOMICS","value":"Primary owner KPI","detail":"labor hours, throughput, equipment, waste, occupancy, and four-wall margin"},{"label":"CHINA & INTERNATIONAL","value":"Primary owner KPI","detail":"transactions, store growth, pricing, competition, licensing, and returns"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Brand and traffic","level":"High","text":"Brand and traffic can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"transactions, value scores, wait times, menu relevance, and competitor share"},{"title":"Labor and execution","level":"High","text":"Labor and execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"wages, scheduling, union activity, turnover, service, and store complexity"},{"title":"China competition","level":"High","text":"China competition can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"price promotion, local brands, store productivity, delivery, and consumer demand"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"U.S. TRANSACTIONS","text":"Track traffic, frequency, ticket, promotions, loyalty, speed, and customer satisfaction and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"STORE ECONOMICS","text":"Track labor hours, throughput, equipment, waste, occupancy, and four-wall margin and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CHINA & INTERNATIONAL","text":"Track transactions, store growth, pricing, competition, licensing, and returns and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies u.s. transactions?","What would cause store economics to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in china & international?","Where does STARBUCKS Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"MCDONALDS CORP, YUM BRANDS INC, Restaurant Brands International Inc., CHIPOTLE MEXICAN GRILL INC, Dutch Bros Inc., LKNCY","comparables":[{"name":"MCDONALDS CORP","ticker":"MCD","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000063908&owner=exclude"},{"name":"YUM BRANDS INC","ticker":"YUM","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001041061&owner=exclude"},{"name":"Restaurant Brands International Inc.","ticker":"QSR","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001618756&owner=exclude"},{"name":"CHIPOTLE MEXICAN GRILL INC","ticker":"CMG","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001058090&owner=exclude"},{"name":"Dutch Bros Inc.","ticker":"BROS","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001866581&owner=exclude"},{"name":"LKNCY","ticker":"LKNCY","ownership":"Public","relationship":"Operating and valuation reference for SBUX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with SBUX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=LKNCY&owner=exclude"}],"sources":[{"title":"SBUX SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000829224&owner=exclude","excerpt":"STARBUCKS CORP filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"SBUX annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000829224&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"SBUX quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000829224&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"SBUX proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000829224&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"SBUX investor relations","meta":"Company primary materials","href":"https://investor.starbucks.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"SBUX official newsroom","meta":"Company announcements","href":"https://about.starbucks.com/press/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}]}', 'Founding editorial research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
